    { const char * tb_v2369 = "// прерывания и службы. Обычные клетки упираются раньше — и службы живут, даже когда клетки съели всё\n"; *(const char * *)tb_grow(v_lines) = tb_v2369; }
    { const char * tb_v2370 = "#define TB_RESERVE (8 << 20)\n"; *(const char * *)tb_grow(v_lines) = tb_v2370; }
