    { const char * tb_v2823 = "// переключение задач: запомнить кадр и «переменные потока» текущей, отдать кадр следующей\n"; *(const char * *)tb_grow(v_lines) = tb_v2823; }
    { const char * tb_v2824 = "TB_API uint64_t *tb_schedule(uint64_t *frame) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2824; }
