    { const char * tb_v3051 = "    for (uint64_t t = 0; t < low >> 21; t++) tb_pdir[0][t] = (uint64_t)(uintptr_t)tb_pt[t] | 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v3051; }
    { const char * tb_v3052 = "    for (uint64_t a = low; a < tb_ram_end; a += 0x200000ull) tb_pdir[a >> 30][(a >> 21) & 511] = a | 0x83;\n"; *(const char * *)tb_grow(v_lines) = tb_v3052; }
    { const char * tb_v3053 = "    // окна устройств PCI (AHCI, NVMe, APIC ...) — от 3 до 4 ГБ, без кэша; память там не трогаем\n"; *(const char * *)tb_grow(v_lines) = tb_v3053; }
