    { const char * tb_v3057 = "    // CR0.WP: и ядро не может писать в страницы «только читать»\n"; *(const char * *)tb_grow(v_lines) = tb_v3057; }
    { const char * tb_v3058 = "    __asm__ volatile(\"movq %0, %%cr3\\nmovq %%cr0, %%rax\\norq $0x10000, %%rax\\nmovq %%rax, %%cr0\\n\" : : \"r\"(tb_pml4) : \"rax\", \"memory\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3058; }
