    { const char * tb_v3098 = "// Что уходит из клетки (аргументы background, текст в канале, список через move), становится\n"; *(const char * *)tb_grow(v_lines) = tb_v3098; }
    { const char * tb_v3099 = "// ничьим (метка 0, «ядро») или переходит получателю. Упала клетка — ядро возвращает всё, что\n"; *(const char * *)tb_grow(v_lines) = tb_v3099; }
    { const char * tb_v3100 = "// у неё осталось: этого больше никто не видит.\n"; *(const char * *)tb_grow(v_lines) = tb_v3100; }
