    { const char * tb_v3151 = "    // замки, которые клетка держала, отпускаем: иначе на них застрянут другие\n"; *(const char * *)tb_grow(v_lines) = tb_v3151; }
    { const char * tb_v3152 = "    for (int i = 0; i < s->nlocks; i++) __atomic_store_n(s->locks[i], 0, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v3152; }
    { const char * tb_v3153 = "    s->nlocks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3153; }
