    { const char * tb_v3174 = "    else if (v == 14 && a < 4096) what = \"обращение по пустому адресу (адрес 0)\";\n"; *(const char * *)tb_grow(v_lines) = tb_v3174; }
    { const char * tb_v3175 = "    else if (v == 14 && (f[TB_F_ERR] & 2) && a >= (uint64_t)(uintptr_t)tb_code_start && a < (uint64_t)(uintptr_t)tb_code_end) what = \"запись в код программы\";\n"; *(const char * *)tb_grow(v_lines) = tb_v3175; }
    { const char * tb_v3176 = "    else if (v == 14) what = \"обращение к памяти, которой нет\";\n"; *(const char * *)tb_grow(v_lines) = tb_v3176; }
    { const char * tb_v3177 = "    else if (v == 8) what = \"двойная ошибка процессора\";\n"; *(const char * *)tb_grow(v_lines) = tb_v3177; }
    { const char * tb_v3178 = "    else what = v < 20 && tb_fault_name[v][0] ? tb_fault_name[v] : \"ошибка процессора\";\n"; *(const char * *)tb_grow(v_lines) = tb_v3178; }
    { const char * tb_v3179 = "    if (tb_cell_can_fall()) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3179; }
