    { const char * tb_v3184 = "    tb_panic(what, v == 14 || v == 8 ? a : v, rip);\n"; *(const char * *)tb_grow(v_lines) = tb_v3184; }
    { const char * tb_v3185 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3185; }
    { const char * tb_v3186 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3186; }
    { const char * tb_v3187 = "// все прерывания приходят сюда; ответ — кадр, в который вернуться (так переключаются задачи)\n"; *(const char * *)tb_grow(v_lines) = tb_v3187; }
    { const char * tb_v3188 = "__attribute__((used)) static uint64_t *tb_isr(uint64_t *f) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3188; }
    { const char * tb_v3189 = "    uint64_t v = f[TB_F_VEC];\n"; *(const char * *)tb_grow(v_lines) = tb_v3189; }
    { const char * tb_v3190 = "    if (v < 32) return tb_fault(v, f);\n"; *(const char * *)tb_grow(v_lines) = tb_v3190; }
    { const char * tb_v3191 = "    if (v == 48) return tb_schedule(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v3191; }
    { const char * tb_v3192 = "    if (v == 49) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3192; }
    { const char * tb_v3193 = "        // таймер своего ядра процессора (APIC): 1000 раз в секунду\n"; *(const char * *)tb_grow(v_lines) = tb_v3193; }
    { const char * tb_v3194 = "        tb_lapic_w(0xB0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v3194; }
    { const char * tb_v3195 = "        if (--tb_me()->slice <= 0) return tb_schedule(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v3195; }
    { const char * tb_v3196 = "        return f;\n"; *(const char * *)tb_grow(v_lines) = tb_v3196; }
    { const char * tb_v3197 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3197; }
    { const char * tb_v3198 = "    int irq = (int)v - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v3198; }
    { const char * tb_v3199 = "    if (irq == 0) tb_ms++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3199; }
    { const char * tb_v3200 = "    if (irq == 1) tb_key_irq();\n"; *(const char * *)tb_grow(v_lines) = tb_v3200; }
    { const char * tb_v3201 = "    if (tb_irq_fn[irq]) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3201; }
    { const char * tb_v3202 = "        // своя функция прерывания: со своими «переменными потока»\n"; *(const char * *)tb_grow(v_lines) = tb_v3202; }
    { const char * tb_v3203 = "        tb_cpu *c = tb_me();\n"; *(const char * *)tb_grow(v_lines) = tb_v3203; }
    { const char * tb_v3204 = "        tb_set_fs(tb_tls_tp(c->irq_tls));\n"; *(const char * *)tb_grow(v_lines) = tb_v3204; }
    { const char * tb_v3205 = "        tb_irq_fn[irq]();\n"; *(const char * *)tb_grow(v_lines) = tb_v3205; }
    { const char * tb_v3206 = "        tb_set_fs(tb_tls_tp(c->run >= 0 ? tb_slots[c->run].tls : c->irq_tls));\n"; *(const char * *)tb_grow(v_lines) = tb_v3206; }
    { const char * tb_v3207 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3207; }
    { const char * tb_v3208 = "    if (irq >= 8) tb_outb(0xA0, 0x20);\n"; *(const char * *)tb_grow(v_lines) = tb_v3208; }
    { const char * tb_v3209 = "    tb_outb(0x20, 0x20);\n"; *(const char * *)tb_grow(v_lines) = tb_v3209; }
    { const char * tb_v3210 = "    if (irq == 0 && --tb_me()->slice <= 0) return tb_schedule(f);\n"; *(const char * *)tb_grow(v_lines) = tb_v3210; }
    { const char * tb_v3211 = "    return f;\n"; *(const char * *)tb_grow(v_lines) = tb_v3211; }
    { const char * tb_v3212 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3212; }
    { const char * tb_v3213 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3213; }
    { const char * tb_v3214 = "TB_API void tb_idt_set(int v, uint64_t a, int ist) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3214; }
    { const char * tb_v3215 = "    tb_idt[2 * v] = (a & 0xFFFFu) | (0x08ull << 16) | ((uint64_t)ist << 32) | (0x8Eull << 40) | (((a >> 16) & 0xFFFFu) << 48);\n"; *(const char * *)tb_grow(v_lines) = tb_v3215; }
