    { const char * tb_v3223 = "// TSS ядра процессора i: ist1 — его стек для двойной ошибки\n"; *(const char * *)tb_grow(v_lines) = tb_v3223; }
    { const char * tb_v3224 = "TB_API void tb_tss_make(int i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3224; }
    { const char * tb_v3225 = "    tb_tss64 *t = &tb_tsss[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v3225; }
    { const char * tb_v3226 = "    t->ist[0] = (uint64_t)(uintptr_t)(tb_cpus[i].df_stack + sizeof tb_cpus[i].df_stack);\n"; *(const char * *)tb_grow(v_lines) = tb_v3226; }
    { const char * tb_v3227 = "    t->iomap = sizeof *t;\n"; *(const char * *)tb_grow(v_lines) = tb_v3227; }
