    { const char * tb_v3229 = "    tb_gdt[3 + 2 * i] = (sizeof *t - 1) | ((a & 0xFFFFFFull) << 16) | (0x89ull << 40) | (((a >> 24) & 0xFF) << 56);\n"; *(const char * *)tb_grow(v_lines) = tb_v3229; }
    { const char * tb_v3230 = "    tb_gdt[4 + 2 * i] = a >> 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v3230; }
