    { const char * tb_v3234 = "    __asm__ volatile(\"wrmsr\" : : \"c\"(0xC0000101u), \"a\"((uint32_t)v), \"d\"((uint32_t)(v >> 32)) : \"memory\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3234; }
    { const char * tb_v3235 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3235; }
    { const char * tb_v3236 = "// пустой ход ядра процессора: ждать прерывания\n"; *(const char * *)tb_grow(v_lines) = tb_v3236; }
    { const char * tb_v3237 = "__attribute__((noreturn)) TB_API void tb_idle(void) { for (;;) __asm__ volatile(\"sti\\nhlt\"); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3237; }
    { const char * tb_v3238 = "// запись ядра процессора: стек и кадр пустого хода, переменные потока для прерываний\n"; *(const char * *)tb_grow(v_lines) = tb_v3238; }
    { const char * tb_v3239 = "TB_API void tb_cpu_init(tb_cpu *c, int id) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3239; }
    { const char * tb_v3240 = "    c->self = c; c->id = id; c->run = -1; c->slice = 10; c->prev = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3240; }
    { const char * tb_v3241 = "    unsigned char *tp = tb_tls_fresh(c->irq_tls);\n"; *(const char * *)tb_grow(v_lines) = tb_v3241; }
    { const char * tb_v3242 = "    *(int *)(tp - ((unsigned char *)tb_tls_self() - (unsigned char *)&tb_in_irq)) = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3242; }
