    { const char * tb_v3249 = "    fr[TB_F_RIP + 3] = (uint64_t)(uintptr_t)(top - 8); fr[TB_F_RIP + 4] = 0x10;\n"; *(const char * *)tb_grow(v_lines) = tb_v3249; }
    { const char * tb_v3250 = "    c->idle_frame = fr;\n"; *(const char * *)tb_grow(v_lines) = tb_v3250; }
    { const char * tb_v3251 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3251; }
    { const char * tb_v3252 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3252; }
    { const char * tb_v3253 = "// --- несколько ядер процессора («звёзды») ---\n"; *(const char * *)tb_grow(v_lines) = tb_v3253; }
    { const char * tb_v3254 = "// Какие ядра есть — из таблицы ACPI «APIC» (MADT). Каждое будим так: INIT, потом дважды\n"; *(const char * *)tb_grow(v_lines) = tb_v3254; }
    { const char * tb_v3255 = "// SIPI с адресом 0x8000; там маленький код (ниже) переводит ядро из 16 бит сразу в 64\n"; *(const char * *)tb_grow(v_lines) = tb_v3255; }
    { const char * tb_v3256 = "// и прыгает в tb_ap_main со своим стеком.\n"; *(const char * *)tb_grow(v_lines) = tb_v3256; }
    { const char * tb_v3257 = "TB_API int tb_apic_ids[TB_NCPU];\n"; *(const char * *)tb_grow(v_lines) = tb_v3257; }
    { const char * tb_v3258 = "// таблицы ACPI лежат выше памяти, которую назвал загрузчик: показываем их кусок 2 МБ (только читать)\n"; *(const char * *)tb_grow(v_lines) = tb_v3258; }
    { const char * tb_v3259 = "TB_API void tb_map_2m(uint64_t a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3259; }
    { const char * tb_v3260 = "    if (a >= (4ull << 30) || a < (uint64_t)(uintptr_t)tb_heap_area) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3260; }
    { const char * tb_v3261 = "    uint64_t *e = &tb_pdir[a >> 30][(a >> 21) & 511];\n"; *(const char * *)tb_grow(v_lines) = tb_v3261; }
    { const char * tb_v3262 = "    if (*e) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3262; }
    { const char * tb_v3263 = "    tb_pdpt[a >> 30] = (uint64_t)(uintptr_t)tb_pdir[a >> 30] | 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v3263; }
    { const char * tb_v3264 = "    *e = (a & ~0x1FFFFFull) | 0x81;\n"; *(const char * *)tb_grow(v_lines) = tb_v3264; }
    { const char * tb_v3265 = "    __asm__ volatile(\"invlpg (%0)\" : : \"r\"(a) : \"memory\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3265; }
    { const char * tb_v3266 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3266; }
    { const char * tb_v3267 = "TB_API int tb_find_cpus(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3267; }
    { const char * tb_v3268 = "    unsigned char *rsdp = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3268; }
    { const char * tb_v3269 = "    for (uint64_t a = 0xE0000; a < 0x100000 && !rsdp; a += 16)\n"; *(const char * *)tb_grow(v_lines) = tb_v3269; }
