    { const char * tb_v4608 = "    long long lim = tb_stack_lim;\n"; *(const char * *)tb_grow(v_lines) = tb_v4608; }
    { const char * tb_v4609 = "    if (lim == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4609; }
    { const char * tb_v4610 = "        lim = 8LL << 20;\n"; *(const char * *)tb_grow(v_lines) = tb_v4610; }
    { const char * tb_v4611 = "        struct rlimit rl;\n"; *(const char * *)tb_grow(v_lines) = tb_v4611; }
    { const char * tb_v4612 = "        if (getrlimit(RLIMIT_STACK, &rl) == 0 && rl.rlim_cur != RLIM_INFINITY) lim = (long long)rl.rlim_cur;\n"; *(const char * *)tb_grow(v_lines) = tb_v4612; }
    { const char * tb_v4613 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4613; }
