    { const char * tb_v4615 = "    if (tb_main_sp && a <= tb_main_sp + 65536 && a >= tb_main_sp - lim - (1 << 20))\n"; *(const char * *)tb_grow(v_lines) = tb_v4615; }
    { const char * tb_v4616 = "        m = tb_lang_en_v == 1 ? \"the stack is full: a function calls itself too deep (endless recursion?)\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v4616; }
    { const char * tb_v4617 = "                              : \"стек переполнен: функция зовёт себя слишком глубоко (рекурсия без конца?)\\n\";\n"; *(const char * *)tb_grow(v_lines) = tb_v4617; }
    { const char * tb_v4618 = "    else\n"; *(const char * *)tb_grow(v_lines) = tb_v4618; }
    { const char * tb_v4619 = "        m = tb_lang_en_v == 1 ? \"the program crashed: memory error. This is a Tachbit bug, not yours: please send this program\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v4619; }
    { const char * tb_v4620 = "                              : \"программа упала: ошибка памяти. Это ошибка Tachbit, а не твоя: пришли, пожалуйста, эту программу\\n\";\n"; *(const char * *)tb_grow(v_lines) = tb_v4620; }
    { const char * tb_v4621 = "    if (write(2, m, strlen(m)) < 0) _exit(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4621; }
    { const char * tb_v4622 = "    _exit(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4622; }
