    { const char * tb_v4624 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4624; }
    { const char * tb_v4625 = "// свой маленький стек для сообщения: у главного потока — постоянный, у остальных — из malloc\n"; *(const char * *)tb_grow(v_lines) = tb_v4625; }
