    { const char * tb_v4632 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4632; }
    { const char * tb_v4633 = "// поток background или ядра: сначала ставим защиту стека, потом сама работа\n"; *(const char * *)tb_grow(v_lines) = tb_v4633; }
    { const char * tb_v4634 = "// сколько потоков background / ядер работает сейчас: уборка памяти ждёт, пока их нет\n"; *(const char * *)tb_grow(v_lines) = tb_v4634; }
    { const char * tb_v4635 = "TB_API int tb_gthreads = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4635; }
    { const char * tb_v4636 = "// короткое ожидание без сна (подсказка процессору)\n"; *(const char * *)tb_grow(v_lines) = tb_v4636; }
    { const char * tb_v4637 = "#if defined(__x86_64__) || defined(__i386__)\n"; *(const char * *)tb_grow(v_lines) = tb_v4637; }
