    { const char * tb_v4643 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4643; }
    { const char * tb_v4644 = "typedef struct { void *(*run)(void *); void *arg; } tb_tramp;\n"; *(const char * *)tb_grow(v_lines) = tb_v4644; }
