    { const char * tb_v4656 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4656; }
    { const char * tb_v4657 = "// поток с 8 МБ стека (на Mac по умолчанию всего 512 КБ) и с понятным сообщением при переполнении\n"; *(const char * *)tb_grow(v_lines) = tb_v4657; }
    { const char * tb_v4658 = "TB_API int tb_thread_create(pthread_t *th, void *(*run)(void *), void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4658; }
