    { const char * tb_v4669 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v4669; }
    { const char * tb_v4670 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4670; }
    { const char * tb_v4671 = "#ifdef _WIN32\n"; *(const char * *)tb_grow(v_lines) = tb_v4671; }
