    { const char * tb_v4678 = "                                            : \"стек переполнен: функция зовёт себя слишком глубоко (рекурсия без конца?)\\n\")\n"; *(const char * *)tb_grow(v_lines) = tb_v4678; }
    { const char * tb_v4679 = "// переполнение стека — сразу (это никогда не «нормальное» исключение)\n"; *(const char * *)tb_grow(v_lines) = tb_v4679; }
    { const char * tb_v4680 = "TB_API LONG CALLBACK tb_win_overflow(EXCEPTION_POINTERS *e) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4680; }
