    { const char * tb_v4721 = "    SetErrorMode(SEM_FAILCRITICALERRORS | SEM_NOGPFAULTERRORBOX);\n"; *(const char * *)tb_grow(v_lines) = tb_v4721; }
    { const char * tb_v4722 = "    ULONG g = 65536;\n"; *(const char * *)tb_grow(v_lines) = tb_v4722; }
