    { const char * tb_v4726 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4726; }
    { const char * tb_v4727 = "// main() зовёт tb_guard_init(): на Windows ей нужны ещё argc и argv из main\n"; *(const char * *)tb_grow(v_lines) = tb_v4727; }
    { const char * tb_v4728 = "#define tb_guard_init() tb_win_init(&argc, &argv)\n"; *(const char * *)tb_grow(v_lines) = tb_v4728; }
    { const char * tb_v4729 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v4729; }
    { const char * tb_v4730 = "TB_API void tb_guard_init(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4730; }
    { const char * tb_v4731 = "    tb_lang_en();   // язык узнаём заранее: в обработчике падения уже нельзя читать файлы\n"; *(const char * *)tb_grow(v_lines) = tb_v4731; }
    { const char * tb_v4732 = "    static char alt[65536];\n"; *(const char * *)tb_grow(v_lines) = tb_v4732; }
    { const char * tb_v4733 = "    stack_t ss;\n"; *(const char * *)tb_grow(v_lines) = tb_v4733; }
    { const char * tb_v4734 = "    ss.ss_sp = alt; ss.ss_size = sizeof alt; ss.ss_flags = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4734; }
    { const char * tb_v4735 = "    sigaltstack(&ss, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v4735; }
