    { const char * tb_v4739 = "    sa.sa_flags = SA_SIGINFO | SA_ONSTACK;\n"; *(const char * *)tb_grow(v_lines) = tb_v4739; }
    { const char * tb_v4740 = "    sigaction(SIGSEGV, &sa, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v4740; }
    { const char * tb_v4741 = "    sigaction(SIGBUS, &sa, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v4741; }
    { const char * tb_v4742 = "    char here;\n"; *(const char * *)tb_grow(v_lines) = tb_v4742; }
    { const char * tb_v4743 = "    tb_main_sp = &here;\n"; *(const char * *)tb_grow(v_lines) = tb_v4743; }
    { const char * tb_v4744 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4744; }
    { const char * tb_v4745 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4745; }
    { const char * tb_v4746 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4746; }
    { const char * tb_v4747 = "// ---------- temp: временная память ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4747; }
    { const char * tb_v4748 = "// Внутри блока temp память берётся из больших кусков подряд (быстро, без malloc),\n"; *(const char * *)tb_grow(v_lines) = tb_v4748; }
    { const char * tb_v4749 = "// а в конце блока все куски отдаются разом. У каждого ядра свои куски.\n"; *(const char * *)tb_grow(v_lines) = tb_v4749; }
    { const char * tb_v4750 = "typedef struct { char *mem; long long size, used; } tb_chunk;\n"; *(const char * *)tb_grow(v_lines) = tb_v4750; }
    { const char * tb_v4751 = "typedef struct { int n; long long used; } tb_mark;\n"; *(const char * *)tb_grow(v_lines) = tb_v4751; }
    { const char * tb_v4752 = "TB_API _Thread_local tb_chunk *tb_chunks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4752; }
    { const char * tb_v4753 = "TB_API _Thread_local int tb_nchunks = 0, tb_capchunks = 0, tb_temp_depth = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4753; }
    { const char * tb_v4754 = "TB_API int tb_in_temp(const void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4754; }
    { const char * tb_v4755 = "    for (int i = tb_nchunks - 1; i >= 0; i--) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4755; }
    { const char * tb_v4756 = "        if ((const char *)p >= tb_chunks[i].mem && (const char *)p < tb_chunks[i].mem + tb_chunks[i].size) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4756; }
    { const char * tb_v4757 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4757; }
    { const char * tb_v4758 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4758; }
    { const char * tb_v4759 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4759; }
    { const char * tb_v4760 = "TB_API void *tb_temp_alloc(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4760; }
    { const char * tb_v4761 = "    n = n > 0 ? (n + 15) & ~15LL : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v4761; }
    { const char * tb_v4762 = "    tb_chunk *c = tb_nchunks > 0 ? &tb_chunks[tb_nchunks - 1] : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4762; }
    { const char * tb_v4763 = "    if (c == 0 || c->used + n > c->size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4763; }
    { const char * tb_v4764 = "        long long size = c != 0 ? c->size * 2 : (1LL << 20);\n"; *(const char * *)tb_grow(v_lines) = tb_v4764; }
    { const char * tb_v4765 = "        if (size < n) size = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v4765; }
    { const char * tb_v4766 = "        if (tb_nchunks == tb_capchunks) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4766; }
    { const char * tb_v4767 = "            tb_capchunks = tb_capchunks * 2 + 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v4767; }
    { const char * tb_v4768 = "            tb_chunks = realloc(tb_chunks, sizeof(tb_chunk) * tb_capchunks);\n"; *(const char * *)tb_grow(v_lines) = tb_v4768; }
    { const char * tb_v4769 = "            if (tb_chunks == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4769; }
    { const char * tb_v4770 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v4770; }
    { const char * tb_v4771 = "        char *mem = malloc(size);\n"; *(const char * *)tb_grow(v_lines) = tb_v4771; }
    { const char * tb_v4772 = "        if (mem == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4772; }
    { const char * tb_v4773 = "        tb_chunks[tb_nchunks] = (tb_chunk){mem, size, 0};\n"; *(const char * *)tb_grow(v_lines) = tb_v4773; }
    { const char * tb_v4774 = "        c = &tb_chunks[tb_nchunks];\n"; *(const char * *)tb_grow(v_lines) = tb_v4774; }
    { const char * tb_v4775 = "        tb_nchunks += 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4775; }
    { const char * tb_v4776 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4776; }
    { const char * tb_v4777 = "    void *p = c->mem + c->used;\n"; *(const char * *)tb_grow(v_lines) = tb_v4777; }
    { const char * tb_v4778 = "    c->used += n;\n"; *(const char * *)tb_grow(v_lines) = tb_v4778; }
    { const char * tb_v4779 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v4779; }
    { const char * tb_v4780 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4780; }
    { const char * tb_v4781 = "// метки открытых temp (и арен шага / функции): самая последняя — текущая область\n"; *(const char * *)tb_grow(v_lines) = tb_v4781; }
    { const char * tb_v4782 = "TB_API _Thread_local tb_mark *tb_marks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4782; }
    { const char * tb_v4783 = "TB_API _Thread_local int tb_capmarks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4783; }
    { const char * tb_v4784 = "TB_INL tb_mark tb_temp_begin(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4784; }
    { const char * tb_v4785 = "    tb_mark m = {tb_nchunks, tb_nchunks > 0 ? tb_chunks[tb_nchunks - 1].used : 0};\n"; *(const char * *)tb_grow(v_lines) = tb_v4785; }
    { const char * tb_v4786 = "    if (tb_temp_depth == tb_capmarks) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4786; }
    { const char * tb_v4787 = "        tb_capmarks = tb_capmarks * 2 + 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v4787; }
    { const char * tb_v4788 = "        tb_marks = realloc(tb_marks, sizeof(tb_mark) * tb_capmarks);\n"; *(const char * *)tb_grow(v_lines) = tb_v4788; }
    { const char * tb_v4789 = "        if (tb_marks == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4789; }
    { const char * tb_v4790 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4790; }
    { const char * tb_v4791 = "    tb_marks[tb_temp_depth] = m;\n"; *(const char * *)tb_grow(v_lines) = tb_v4791; }
    { const char * tb_v4792 = "    tb_temp_depth += 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4792; }
    { const char * tb_v4793 = "    return m;\n"; *(const char * *)tb_grow(v_lines) = tb_v4793; }
    { const char * tb_v4794 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4794; }
    { const char * tb_v4795 = "// p во временной памяти текущей (самой внутренней) области, а не во внешней\n"; *(const char * *)tb_grow(v_lines) = tb_v4795; }
    { const char * tb_v4796 = "TB_API int tb_in_cur_temp(const void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4796; }
    { const char * tb_v4797 = "    if (tb_temp_depth == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4797; }
    { const char * tb_v4798 = "    tb_mark t = tb_marks[tb_temp_depth - 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v4798; }
    { const char * tb_v4799 = "    for (int i = tb_nchunks - 1; i >= 0; i--) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4799; }
    { const char * tb_v4800 = "        const char *m = tb_chunks[i].mem;\n"; *(const char * *)tb_grow(v_lines) = tb_v4800; }
    { const char * tb_v4801 = "        if ((const char *)p >= m && (const char *)p < m + tb_chunks[i].size)\n"; *(const char * *)tb_grow(v_lines) = tb_v4801; }
    { const char * tb_v4802 = "            return i > t.n - 1 || (i == t.n - 1 && (const char *)p - m >= t.used);\n"; *(const char * *)tb_grow(v_lines) = tb_v4802; }
    { const char * tb_v4803 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4803; }
    { const char * tb_v4804 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4804; }
    { const char * tb_v4805 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4805; }
    { const char * tb_v4806 = "// длина последних текстов: s[i] в цикле не пересчитывает strlen каждый раз\n"; *(const char * *)tb_grow(v_lines) = tb_v4806; }
    { const char * tb_v4807 = "TB_API _Thread_local const char *tb_lc_p[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v4807; }
    { const char * tb_v4808 = "TB_API _Thread_local long long tb_lc_n[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v4808; }
    { const char * tb_v4809 = "TB_API _Thread_local int tb_lc_next;\n"; *(const char * *)tb_grow(v_lines) = tb_v4809; }
    { const char * tb_v4810 = "TB_INL void tb_u8c_clear(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v4810; }
    { const char * tb_v4811 = "TB_INL void tb_lc_clear(void) { tb_lc_p[0] = 0; tb_lc_p[1] = 0; tb_u8c_clear(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4811; }
    { const char * tb_v4812 = "TB_INL void tb_temp_end(tb_mark m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4812; }
    { const char * tb_v4813 = "    // первый кусок оставляем пустым: следующий temp возьмёт его без malloc\n"; *(const char * *)tb_grow(v_lines) = tb_v4813; }
    { const char * tb_v4814 = "    while (tb_nchunks > m.n && tb_nchunks > 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4814; }
    { const char * tb_v4815 = "        tb_nchunks -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4815; }
    { const char * tb_v4816 = "        free(tb_chunks[tb_nchunks].mem);\n"; *(const char * *)tb_grow(v_lines) = tb_v4816; }
    { const char * tb_v4817 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4817; }
    { const char * tb_v4818 = "    if (tb_nchunks > m.n) tb_chunks[0].used = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4818; }
    { const char * tb_v4819 = "    else if (tb_nchunks > 0) tb_chunks[tb_nchunks - 1].used = m.used;\n"; *(const char * *)tb_grow(v_lines) = tb_v4819; }
    { const char * tb_v4820 = "    tb_temp_depth -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4820; }
    { const char * tb_v4821 = "    tb_lc_clear();\n"; *(const char * *)tb_grow(v_lines) = tb_v4821; }
    { const char * tb_v4822 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4822; }
    { const char * tb_v4823 = "// --llvm: то же через указатель (из файла .ll так проще, чем отдавать struct по значению)\n"; *(const char * *)tb_grow(v_lines) = tb_v4823; }
    { const char * tb_v4824 = "TB_INL void tb_temp_begin_p(tb_mark *m) { *m = tb_temp_begin(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4824; }
    { const char * tb_v4825 = "TB_INL void tb_temp_end_p(tb_mark *m) { tb_temp_end(*m); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4825; }
    { const char * tb_v4826 = "// память функции: своя область, только если функцию позвали не изнутри другой области\n"; *(const char * *)tb_grow(v_lines) = tb_v4826; }
    { const char * tb_v4827 = "TB_INL int tb_fa_begin(tb_mark *m) { if (tb_temp_depth != 0) return 0; *m = tb_temp_begin(); return 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4827; }
    { const char * tb_v4828 = "TB_INL void tb_fa_end(int fa, tb_mark *m) { if (fa) tb_temp_end(*m); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4828; }
    { const char * tb_v4829 = "// ---------- уборка памяти: сборщик мусора ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4829; }
    { const char * tb_v4830 = "// Шаги циклов, функции и temp уже отдают память сами (своя временная память).\n"; *(const char * *)tb_grow(v_lines) = tb_v4830; }
    { const char * tb_v4831 = "// А то, что живёт дольше (obj, списки, dict, тексты), раньше жило до конца программы.\n"; *(const char * *)tb_grow(v_lines) = tb_v4831; }
    { const char * tb_v4832 = "// Теперь иногда (когда набралось много новой памяти) программа делает обход:\n"; *(const char * *)tb_grow(v_lines) = tb_v4832; }
    { const char * tb_v4833 = "//   1) смотрит, что видно из переменных: стек, общие (shared) переменные, временная память;\n"; *(const char * *)tb_grow(v_lines) = tb_v4833; }
    { const char * tb_v4834 = "//   2) от них идёт по всему, на что они указывают, и помечает это «нужно»;\n"; *(const char * *)tb_grow(v_lines) = tb_v4834; }
    { const char * tb_v4835 = "//   3) всё не помеченное — мусор, его место отдаётся под новые значения.\n"; *(const char * *)tb_grow(v_lines) = tb_v4835; }
    { const char * tb_v4836 = "// Обход идёт, только когда работает один поток: пока идут background или on all cores, ждём.\n"; *(const char * *)tb_grow(v_lines) = tb_v4836; }
    { const char * tb_v4837 = "// TB_GC=0 — выключить уборку (для проверки), TB_GC_STRESS=N — обход на каждом N-м выделении,\n"; *(const char * *)tb_grow(v_lines) = tb_v4837; }
    { const char * tb_v4838 = "// TB_GC_STATS=1 — печатать каждый обход.\n"; *(const char * *)tb_grow(v_lines) = tb_v4838; }
    { const char * tb_v4839 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v4839; }
    { const char * tb_v4840 = "TB_API void *tb_gc_alloc(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4840; }
    { const char * tb_v4841 = "    void *p = malloc(n > 0 ? n : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4841; }
    { const char * tb_v4842 = "    if (p == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4842; }
    { const char * tb_v4843 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v4843; }
    { const char * tb_v4844 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4844; }
    { const char * tb_v4845 = "TB_API void tb_gc_free(void *p) { free(p); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4845; }
    { const char * tb_v4846 = "#define tb_gc_alloc_np tb_gc_alloc\n"; *(const char * *)tb_grow(v_lines) = tb_v4846; }
    { const char * tb_v4847 = "TB_API void *tb_gc_realloc(void *p, long long old_n, long long new_n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4847; }
    { const char * tb_v4848 = "    (void)old_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v4848; }
    { const char * tb_v4849 = "    p = realloc(p, new_n > 0 ? new_n : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4849; }
    { const char * tb_v4850 = "    if (p == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4850; }
    { const char * tb_v4851 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v4851; }
    { const char * tb_v4852 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4852; }
    { const char * tb_v4853 = "#define tb_gc_root(p, n) ((void)(p), (void)(n))\n"; *(const char * *)tb_grow(v_lines) = tb_v4853; }
    { const char * tb_v4854 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v4854; }
    { const char * tb_v4855 = "#include <setjmp.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v4855; }
    { const char * tb_v4856 = "#define TB_GSH 16\n"; *(const char * *)tb_grow(v_lines) = tb_v4856; }
    { const char * tb_v4857 = "#define TB_GPG (1LL << TB_GSH)\n"; *(const char * *)tb_grow(v_lines) = tb_v4857; }
    { const char * tb_v4858 = "#define TB_GNC 37\n"; *(const char * *)tb_grow(v_lines) = tb_v4858; }
    { const char * tb_v4859 = "#define TB_GBIG 32768\n"; *(const char * *)tb_grow(v_lines) = tb_v4859; }
    { const char * tb_v4860 = "// размеры мелких блоков: страница 64 КБ делится на блоки одного размера (шаг 8 байт у мелких — плотно, как подряд)\n"; *(const char * *)tb_grow(v_lines) = tb_v4860; }
    { const char * tb_v4861 = "TB_API const long long tb_gsz[TB_GNC] = {16, 24, 32, 40, 48, 56, 64, 72, 80, 96, 112, 128, 160, 192, 224, 256,\n"; *(const char * *)tb_grow(v_lines) = tb_v4861; }
    { const char * tb_v4862 = "    320, 384, 448, 512, 640, 768, 1024, 1280, 1536, 2048, 2560, 3072, 4096, 5120, 6144, 8192, 10240, 12288,\n"; *(const char * *)tb_grow(v_lines) = tb_v4862; }
    { const char * tb_v4863 = "    16384, 21840, 32768};\n"; *(const char * *)tb_grow(v_lines) = tb_v4863; }
