    { const char * tb_v4920 = "// munmap здесь зовётся только для целого куска из tb_gsys — это VirtualFree(MEM_RELEASE).\n"; *(const char * *)tb_grow(v_lines) = tb_v4920; }
    { const char * tb_v4921 = "TB_API char *tb_gsys(long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4921; }
    { const char * tb_v4922 = "    char *m = VirtualAlloc(0, (SIZE_T)size, MEM_RESERVE | MEM_COMMIT, PAGE_READWRITE);\n"; *(const char * *)tb_grow(v_lines) = tb_v4922; }
