    { const char * tb_v4936 = "extern void *mremap(void *old, size_t old_size, size_t new_size, int flags, ...);\n"; *(const char * *)tb_grow(v_lines) = tb_v4936; }
    { const char * tb_v4937 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v4937; }
    { const char * tb_v4938 = "TB_API char *tb_gsys(long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4938; }
    { const char * tb_v4939 = "    size_t tot = (size_t)size + (size_t)TB_GPG;\n"; *(const char * *)tb_grow(v_lines) = tb_v4939; }
