    { const char * tb_v4972 = "    return pg;\n"; *(const char * *)tb_grow(v_lines) = tb_v4972; }
    { const char * tb_v4973 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4973; }
    { const char * tb_v4974 = "#define TB_GIDX(pg, off) ((long long)(((unsigned long long)(off) * (pg)->inv) >> 32))\n"; *(const char * *)tb_grow(v_lines) = tb_v4974; }
    { const char * tb_v4975 = "// блок, внутрь которого указывает адрес a (или 0, если это не наша занятая память)\n"; *(const char * *)tb_grow(v_lines) = tb_v4975; }
    { const char * tb_v4976 = "TB_INL char *tb_gblock(uintptr_t a, tb_gpage **out) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4976; }
    { const char * tb_v4977 = "    if (a < tb_glo || a >= tb_ghi) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4977; }
