    { const char * tb_v4989 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4989; }
    { const char * tb_v4990 = "TB_API void tb_gc_collect(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v4990; }
    { const char * tb_v4991 = "TB_API void *tb_galloc_locked(long long n, int np) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4991; }
    { const char * tb_v4992 = "    if (!tb_gready) tb_gsetup();\n"; *(const char * *)tb_grow(v_lines) = tb_v4992; }
    { const char * tb_v4993 = "    if (n <= 0) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4993; }
