    { const char * tb_v4995 = "    if (n >= 64) n += 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4995; }
    { const char * tb_v4996 = "    if (TB_RARE(tb_gsince >= tb_gnext || tb_gstress) && !tb_goff && tb_gtop &&\n"; *(const char * *)tb_grow(v_lines) = tb_v4996; }
    { const char * tb_v4997 = "        __atomic_load_n(&tb_gthreads, __ATOMIC_ACQUIRE) == 0 &&\n"; *(const char * *)tb_grow(v_lines) = tb_v4997; }
    { const char * tb_v4998 = "        (tb_gsince >= tb_gnext || (tb_gstress && ++tb_gcount % tb_gstress == 0)))\n"; *(const char * *)tb_grow(v_lines) = tb_v4998; }
    { const char * tb_v4999 = "        tb_gc_collect();\n"; *(const char * *)tb_grow(v_lines) = tb_v4999; }
    { const char * tb_v5000 = "    if (n <= TB_GBIG) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5000; }
    { const char * tb_v5001 = "        int cls = tb_gcls[(n + 7) >> 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v5001; }
