    { const char * tb_v5402 = "        memset(l->data + old, 0, l->cap / 8 - old);\n"; *(const char * *)tb_grow(v_lines) = tb_v5402; }
    { const char * tb_v5403 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5403; }
