    { const char * tb_v5432 = "// значения dict bool лежат байтами — в list bool их надо переложить в биты\n"; *(const char * *)tb_grow(v_lines) = tb_v5432; }
    { const char * tb_v5433 = "TB_API tb_list *tb_bits_of_bytes(tb_list *b) { return tb_bits_from(b->len, (const unsigned char *)b->data); }\n"; *(const char * *)tb_grow(v_lines) = tb_v5433; }
    { const char * tb_v5434 = "// N одинаковых элементов в конец (repeat N times: nums.add(0))\n"; *(const char * *)tb_grow(v_lines) = tb_v5434; }
    { const char * tb_v5435 = "TB_API void tb_fill(tb_list *l, long long n, const void *v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5435; }
    { const char * tb_v5436 = "    if (n <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v5436; }
    { const char * tb_v5437 = "    if (l->len + n > l->cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5437; }
    { const char * tb_v5438 = "        if (l->cap < 0) tb_crash(0, \"список нельзя растить, пока по нему идёт each ... by N (и сам кусок растить нельзя)\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5438; }
    { const char * tb_v5439 = "        long long cap = l->cap * 2 + 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v5439; }
