    { const char * tb_v5503 = "// сколько букв в первых nb байтах\n"; *(const char * *)tb_grow(v_lines) = tb_v5503; }
    { const char * tb_v5504 = "TB_API long long tb_u8count(const char *s, long long nb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5504; }
    { const char * tb_v5505 = "    const unsigned char *p = (const unsigned char *)s, *e = p + nb;\n"; *(const char * *)tb_grow(v_lines) = tb_v5505; }
    { const char * tb_v5506 = "    long long n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5506; }
    { const char * tb_v5507 = "    while (p < e) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5507; }
    { const char * tb_v5508 = "        if (*p < 0x80) { p++; n++; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5508; }
