    { const char * tb_v5531 = "            if (b > 0 && (unsigned char)s[b - 1] >= 0xC0) from = b - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v5531; }
    { const char * tb_v5532 = "            c->nl = c->nl - tb_u8count(s + from, c->nb - from) + tb_u8count(s + from, nb - from);\n"; *(const char * *)tb_grow(v_lines) = tb_v5532; }
    { const char * tb_v5533 = "            c->nb = nb;\n"; *(const char * *)tb_grow(v_lines) = tb_v5533; }
    { const char * tb_v5534 = "            if (c->bi > from) { c->li = 0; c->bi = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5534; }
    { const char * tb_v5535 = "            return c;\n"; *(const char * *)tb_grow(v_lines) = tb_v5535; }
    { const char * tb_v5536 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v5536; }
    { const char * tb_v5537 = "        break;\n"; *(const char * *)tb_grow(v_lines) = tb_v5537; }
    { const char * tb_v5538 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5538; }
    { const char * tb_v5539 = "    tb_u8slot *c = &tb_u8c[tb_u8c_next];\n"; *(const char * *)tb_grow(v_lines) = tb_v5539; }
    { const char * tb_v5540 = "    tb_u8c_next = (tb_u8c_next + 1) & 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v5540; }
    { const char * tb_v5541 = "    c->p = s;\n"; *(const char * *)tb_grow(v_lines) = tb_v5541; }
