    { const char * tb_v5543 = "    c->nl = tb_u8count(s, c->nb);\n"; *(const char * *)tb_grow(v_lines) = tb_v5543; }
    { const char * tb_v5544 = "    c->li = 0; c->bi = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5544; }
    { const char * tb_v5545 = "    return c;\n"; *(const char * *)tb_grow(v_lines) = tb_v5545; }
    { const char * tb_v5546 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5546; }
    { const char * tb_v5547 = "TB_API long long tb_ulen(const char *s) { return tb_u8info(s, -1)->nl; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5547; }
    { const char * tb_v5548 = "TB_API long long tb_ulen_n(const char *s, long long nb) { return nb < 0 ? tb_ulen(s) : tb_u8info(s, nb)->nl; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5548; }
    { const char * tb_v5549 = "// байт, с которого начинается буква i (i == букв — конец текста)\n"; *(const char * *)tb_grow(v_lines) = tb_v5549; }
    { const char * tb_v5550 = "TB_API long long tb_u8off(tb_u8slot *c, long long i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5550; }
    { const char * tb_v5551 = "    if (c->nl == c->nb) return i;   // одна латиница: буква = байт\n"; *(const char * *)tb_grow(v_lines) = tb_v5551; }
    { const char * tb_v5552 = "    const unsigned char *s = (const unsigned char *)c->p;\n"; *(const char * *)tb_grow(v_lines) = tb_v5552; }
    { const char * tb_v5553 = "    long long li = c->li, bi = c->bi;\n"; *(const char * *)tb_grow(v_lines) = tb_v5553; }
    { const char * tb_v5554 = "    if (i < li && i < li - i) { li = 0; bi = 0; }   // ближе к началу, чем к прошлому месту\n"; *(const char * *)tb_grow(v_lines) = tb_v5554; }
    { const char * tb_v5555 = "    while (li < i) { long long k = tb_u8n(s + bi); if (bi + k > c->nb) k = 1; bi += k; li++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5555; }
    { const char * tb_v5556 = "    while (li > i) {   // назад: на начало предыдущей буквы\n"; *(const char * *)tb_grow(v_lines) = tb_v5556; }
    { const char * tb_v5557 = "        long long b = bi - 1, back = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5557; }
    { const char * tb_v5558 = "        while (b > 0 && (s[b] & 0xC0) == 0x80 && back < 3) { b--; back++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5558; }
    { const char * tb_v5559 = "        if (b + tb_u8n(s + b) != bi) b = bi - 1;   // не сложилось в букву — один байт\n"; *(const char * *)tb_grow(v_lines) = tb_v5559; }
    { const char * tb_v5560 = "        bi = b; li--;\n"; *(const char * *)tb_grow(v_lines) = tb_v5560; }
    { const char * tb_v5561 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5561; }
