    { const char * tb_v5588 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5588; }
    { const char * tb_v5589 = "// each ch in s: буква с байта *i; *i становится последним байтом буквы (цикл сам прибавит 1)\n"; *(const char * *)tb_grow(v_lines) = tb_v5589; }
