    { const char * tb_v5627 = "TB_API void tb_app_n(const char **p, long long *rl, long long *rc, const char *b, long long lb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5627; }
    { const char * tb_v5628 = "    char *s = (char *)*p;\n"; *(const char * *)tb_grow(v_lines) = tb_v5628; }
