    { const char * tb_v5648 = "    memmove(s + *rl, b, lb);\n"; *(const char * *)tb_grow(v_lines) = tb_v5648; }
    { const char * tb_v5649 = "    *rl += lb;\n"; *(const char * *)tb_grow(v_lines) = tb_v5649; }
    { const char * tb_v5650 = "    s[*rl] = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v5650; }
