    { const char * tb_v5660 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5660; }
    { const char * tb_v5661 = "// байты текста (для дисков, сети, форматов файлов): byte_len, byte_at, byte_char\n"; *(const char * *)tb_grow(v_lines) = tb_v5661; }
