    { const char * tb_v5671 = "TB_API long long tb_code(const char *s, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5671; }
    { const char * tb_v5672 = "    if (s[0] == 0) tb_crash(line, \"code: текст пустой\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5672; }
