    { const char * tb_v5679 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v5679; }
    { const char * tb_v5680 = "// char(1087) → \"п\": буква по её номеру в Юникоде\n"; *(const char * *)tb_grow(v_lines) = tb_v5680; }
