    { const char * tb_v5690 = "// переполнение int — остановка с номером строки (внутри danger числа заворачиваются, как в железе)\n"; *(const char * *)tb_grow(v_lines) = tb_v5690; }
    { const char * tb_v5691 = "TB_COLD TB_API void tb_ovf(int line) { tb_crash(line, \"число не помещается в int: больше 9223372036854775807 или меньше -9223372036854775808\"); }\n"; *(const char * *)tb_grow(v_lines) = tb_v5691; }
    { const char * tb_v5692 = "TB_INL long long tb_addo(long long a, long long b, int line) { long long r; if (__builtin_expect(__builtin_add_overflow(a, b, &r), 0)) tb_ovf(line); return r; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5692; }
