    { const char * tb_v5695 = "TB_INL long long tb_nego(long long a, int line) { if (__builtin_expect(a == (-9223372036854775807LL - 1), 0)) tb_ovf(line); return -a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5695; }
    { const char * tb_v5696 = "TB_API long long tb_div(long long a, long long b, int line) { if (b == 0) tb_crash(line, \"деление на ноль\"); if (b == -1) return tb_nego(a, line); return a / b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5696; }
    { const char * tb_v5697 = "TB_API long long tb_mod(long long a, long long b, int line) { if (b == 0) tb_crash(line, \"остаток от деления на ноль\"); if (b == -1) return 0; return a % b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5697; }
