    { const char * tb_v5953 = "        if (ch == '\"' || ch < 32) { sprintf(cmd + k, \"%%%02X\", ch); k += 3; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5953; }
    { const char * tb_v5954 = "        else cmd[k++] = url[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v5954; }
    { const char * tb_v5955 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5955; }
    { const char * tb_v5956 = "    strcpy(cmd + k, \"\\\" 2>NUL\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5956; }
    { const char * tb_v5957 = "    FILE *p = popen(cmd, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5957; }
    { const char * tb_v5958 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v5958; }
    { const char * tb_v5959 = "    size_t k = (size_t)sprintf(cmd, \"curl -fsSL --max-time 30 '\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5959; }
    { const char * tb_v5960 = "    for (size_t i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v5960; }
    { const char * tb_v5961 = "        if (url[i] == '\\'') { memcpy(cmd + k, \"'\\\\''\", 4); k += 4; }\n"; *(const char * *)tb_grow(v_lines) = tb_v5961; }
    { const char * tb_v5962 = "        else cmd[k++] = url[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v5962; }
    { const char * tb_v5963 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v5963; }
    { const char * tb_v5964 = "    strcpy(cmd + k, \"' 2>/dev/null\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5964; }
    { const char * tb_v5965 = "    FILE *p = popen(cmd, \"r\");\n"; *(const char * *)tb_grow(v_lines) = tb_v5965; }
