    { const char * tb_v6013 = "    return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v6013; }
    { const char * tb_v6014 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6014; }
    { const char * tb_v6015 = "// строка JSON (p смотрит на \") → обычный текст\n"; *(const char * *)tb_grow(v_lines) = tb_v6015; }
    { const char * tb_v6016 = "TB_API const char *tb_js_str(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6016; }
    { const char * tb_v6017 = "    const char *e = tb_js_skip(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v6017; }
    { const char * tb_v6018 = "    if (!e) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6018; }
