    { const char * tb_v6317 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v6317; }
    { const char * tb_v6318 = "// ---------- dict: ключи и значения лежат в двух списках по порядку добавления,\n"; *(const char * *)tb_grow(v_lines) = tb_v6318; }
    { const char * tb_v6319 = "// а найти номер по ключу можно тремя способами (mode):\n"; *(const char * *)tb_grow(v_lines) = tb_v6319; }
    { const char * tb_v6320 = "//   1 — «номер = адрес»: ключи int шли подряд base, base+1, base+2 ... — номер = ключ - base, без поиска;\n"; *(const char * *)tb_grow(v_lines) = tb_v6320; }
    { const char * tb_v6321 = "//   2 — «адресное хранение»: ключи int лежат плотно — pos[ключ - base] = номер + 1, один взгляд;\n"; *(const char * *)tb_grow(v_lines) = tb_v6321; }
    { const char * tb_v6322 = "//   0 — таблица slots с хешем (текст или разбросанные числа) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6322; }
    { const char * tb_v6323 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v6323; }
    { const char * tb_v6324 = "    tb_list *keys; tb_list *vals; long long *slots; long long nslots; int text;\n"; *(const char * *)tb_grow(v_lines) = tb_v6324; }
    { const char * tb_v6325 = "    int mode; long long base; long long *pos; long long npos;\n"; *(const char * *)tb_grow(v_lines) = tb_v6325; }
    { const char * tb_v6326 = "} tb_dict;\n"; *(const char * *)tb_grow(v_lines) = tb_v6326; }
    { const char * tb_v6327 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v6327; }
    { const char * tb_v6328 = "// список целиком: сам список, его память и (texts) тексты-элементы\n"; *(const char * *)tb_grow(v_lines) = tb_v6328; }
    { const char * tb_v6329 = "TB_API void tb_export_list(tb_list *l, int texts) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6329; }
    { const char * tb_v6330 = "    if (!l) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6330; }
    { const char * tb_v6331 = "    if (texts) for (long long i = 0; i < l->len; i++) tb_export(((char **)l->data)[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v6331; }
    { const char * tb_v6332 = "    tb_export(l->data);\n"; *(const char * *)tb_grow(v_lines) = tb_v6332; }
    { const char * tb_v6333 = "    tb_export(l);\n"; *(const char * *)tb_grow(v_lines) = tb_v6333; }
    { const char * tb_v6334 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6334; }
    { const char * tb_v6335 = "TB_API void tb_export_dict(tb_dict *d, int ktext, int vtext) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6335; }
    { const char * tb_v6336 = "    if (!d) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6336; }
