    { const char * tb_v6339 = "    tb_export(d->slots);\n"; *(const char * *)tb_grow(v_lines) = tb_v6339; }
    { const char * tb_v6340 = "    tb_export(d->pos);\n"; *(const char * *)tb_grow(v_lines) = tb_v6340; }
    { const char * tb_v6341 = "    tb_export(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v6341; }
    { const char * tb_v6342 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6342; }
    { const char * tb_v6343 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v6343; }
    { const char * tb_v6344 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v6344; }
    { const char * tb_v6345 = "// ячейка таблицы: номер ключа + 1 (младшие 40 бит) и метка из старших битов хеша\n"; *(const char * *)tb_grow(v_lines) = tb_v6345; }
    { const char * tb_v6346 = "#define TB_DAT ((1LL << 40) - 1)\n"; *(const char * *)tb_grow(v_lines) = tb_v6346; }
    { const char * tb_v6347 = "#define TB_DTAG(h) ((long long)(((h) >> 40) << 40) & ~TB_DAT & 0x7FFFFFFFFFFFFFFFLL)\n"; *(const char * *)tb_grow(v_lines) = tb_v6347; }
    { const char * tb_v6348 = "TB_API unsigned long long tb_hash(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6348; }
    { const char * tb_v6349 = "    unsigned long long h = 1469598103934665603ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v6349; }
