    { const char * tb_v6351 = "        for (const unsigned char *p = *(const unsigned char * const *)k; *p; p++) { h ^= *p; h *= 1099511628211ULL; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6351; }
    { const char * tb_v6352 = "    } else {\n"; *(const char * *)tb_grow(v_lines) = tb_v6352; }
