    { const char * tb_v6354 = "        h *= 0x9E3779B97F4A7C15ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v6354; }
    { const char * tb_v6355 = "        h ^= h >> 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v6355; }
