    { const char * tb_v6357 = "    return h;\n"; *(const char * *)tb_grow(v_lines) = tb_v6357; }
    { const char * tb_v6358 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6358; }
    { const char * tb_v6359 = "TB_API int tb_keq(tb_dict *d, const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6359; }
    { const char * tb_v6360 = "    if (d->text) return strcmp(*(const char * const *)a, *(const char * const *)b) == 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6360; }
