    { const char * tb_v6363 = "TB_INL long long tb_dfind(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6363; }
    { const char * tb_v6364 = "    if (d->mode == 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6364; }
