    { const char * tb_v6366 = "        return at < (unsigned long long)d->keys->len ? (long long)at : -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6366; }
    { const char * tb_v6367 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6367; }
    { const char * tb_v6368 = "    if (d->mode == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6368; }
    { const char * tb_v6369 = "        unsigned long long o = (unsigned long long)(*(const long long *)k - d->base);\n"; *(const char * *)tb_grow(v_lines) = tb_v6369; }
