    { const char * tb_v6371 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6371; }
    { const char * tb_v6372 = "    unsigned long long h = tb_hash(d, k), mask = d->nslots - 1, i = h & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v6372; }
    { const char * tb_v6373 = "    long long tag = TB_DTAG(h);\n"; *(const char * *)tb_grow(v_lines) = tb_v6373; }
    { const char * tb_v6374 = "    while (d->slots[i] != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6374; }
    { const char * tb_v6375 = "        long long sl = d->slots[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v6375; }
    { const char * tb_v6376 = "        // метка хеша совпала — только тогда сравниваем сами ключи (текст — дорого)\n"; *(const char * *)tb_grow(v_lines) = tb_v6376; }
    { const char * tb_v6377 = "        if ((sl & ~TB_DAT) == tag) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6377; }
    { const char * tb_v6378 = "            long long at = (sl & TB_DAT) - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6378; }
    { const char * tb_v6379 = "            if (tb_keq(d, d->keys->data + at * d->keys->size, k)) return at;\n"; *(const char * *)tb_grow(v_lines) = tb_v6379; }
    { const char * tb_v6380 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6380; }
    { const char * tb_v6381 = "        i = (i + 1) & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v6381; }
    { const char * tb_v6382 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6382; }
    { const char * tb_v6383 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6383; }
    { const char * tb_v6384 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6384; }
    { const char * tb_v6385 = "// память для таблиц dict — там же, где лежат его ключи (временная или обычная)\n"; *(const char * *)tb_grow(v_lines) = tb_v6385; }
