    { const char * tb_v6395 = "        if (!(tb_nchunks > 0 && tb_in_temp(d->pos))) tb_gc_free(d->pos);\n"; *(const char * *)tb_grow(v_lines) = tb_v6395; }
    { const char * tb_v6396 = "        d->pos = 0; d->npos = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6396; }
    { const char * tb_v6397 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6397; }
    { const char * tb_v6398 = "    d->nslots = nslots;\n"; *(const char * *)tb_grow(v_lines) = tb_v6398; }
    { const char * tb_v6399 = "    d->slots = tb_dalloc(d, d->slots, nslots * sizeof(long long));\n"; *(const char * *)tb_grow(v_lines) = tb_v6399; }
