    { const char * tb_v6461 = "// новый ключ int k: можно ли остаться без поиска (mode 1 или 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v6461; }
    { const char * tb_v6462 = "TB_API void tb_dplace_int(tb_dict *d, long long k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6462; }
    { const char * tb_v6463 = "    long long n = d->keys->len;          // уже вместе с новым ключом\n"; *(const char * *)tb_grow(v_lines) = tb_v6463; }
    { const char * tb_v6464 = "    if (d->mode == 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6464; }
    { const char * tb_v6465 = "        if (n == 1) { d->base = k; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6465; }
    { const char * tb_v6466 = "        if (k == d->base + n - 1) return;  // подряд — остаёмся в mode 1\n"; *(const char * *)tb_grow(v_lines) = tb_v6466; }
    { const char * tb_v6467 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6467; }
    { const char * tb_v6468 = "    if (d->mode == 1 || d->mode == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6468; }
    { const char * tb_v6469 = "        // плотно ли: ключи не дальше 4 ячеек на один ключ\n"; *(const char * *)tb_grow(v_lines) = tb_v6469; }
