    { const char * tb_v6472 = "            if (d->mode == 2 && o < d->npos) { d->pos[o] = n; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6472; }
    { const char * tb_v6473 = "            long long want = d->npos * 2 > o + 1 ? d->npos * 2 : o + 1 + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v6473; }
    { const char * tb_v6474 = "            if (want < 16) want = 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v6474; }
    { const char * tb_v6475 = "            tb_dto_pos(d, want);\n"; *(const char * *)tb_grow(v_lines) = tb_v6475; }
