    { const char * tb_v6477 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6477; }
    { const char * tb_v6478 = "        tb_dto_hash(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v6478; }
    { const char * tb_v6479 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6479; }
    { const char * tb_v6480 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6480; }
    { const char * tb_v6481 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6481; }
    { const char * tb_v6482 = "// место под значение ключа k; если ключа нет — добавить со значением *def\n"; *(const char * *)tb_grow(v_lines) = tb_v6482; }
    { const char * tb_v6483 = "TB_API void *tb_dput(tb_dict *d, const void *k, const void *def) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6483; }
    { const char * tb_v6484 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v6484; }
    { const char * tb_v6485 = "    if (at >= 0) return d->vals->data + at * d->vals->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v6485; }
    { const char * tb_v6486 = "    memcpy(tb_grow(d->keys), k, d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v6486; }
    { const char * tb_v6487 = "    void *v = tb_grow(d->vals);\n"; *(const char * *)tb_grow(v_lines) = tb_v6487; }
    { const char * tb_v6488 = "    if (def) memcpy(v, def, d->vals->size); else memset(v, 0, d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v6488; }
    { const char * tb_v6489 = "    if (d->mode != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6489; }
    { const char * tb_v6490 = "        // без поиска; если ключ лёг далеко, tb_dplace_int сам перейдёт на хеш и впишет все ключи\n"; *(const char * *)tb_grow(v_lines) = tb_v6490; }
    { const char * tb_v6491 = "        tb_dplace_int(d, *(const long long *)k);\n"; *(const char * *)tb_grow(v_lines) = tb_v6491; }
    { const char * tb_v6492 = "        return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v6492; }
    { const char * tb_v6493 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6493; }
    { const char * tb_v6494 = "    if (d->keys->len * 2 > d->nslots) tb_dreindex(d, d->nslots * 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v6494; }
    { const char * tb_v6495 = "    else {\n"; *(const char * *)tb_grow(v_lines) = tb_v6495; }
    { const char * tb_v6496 = "        unsigned long long h = tb_hash(d, k), mask = d->nslots - 1, i = h & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v6496; }
    { const char * tb_v6497 = "        while (d->slots[i] != 0) i = (i + 1) & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v6497; }
    { const char * tb_v6498 = "        d->slots[i] = d->keys->len | TB_DTAG(h);\n"; *(const char * *)tb_grow(v_lines) = tb_v6498; }
    { const char * tb_v6499 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6499; }
    { const char * tb_v6500 = "    return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v6500; }
    { const char * tb_v6501 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6501; }
    { const char * tb_v6502 = "TB_API void *tb_dget(tb_dict *d, const void *k, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6502; }
    { const char * tb_v6503 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v6503; }
    { const char * tb_v6504 = "    if (TB_RARE(at < 0)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6504; }
    { const char * tb_v6505 = "        if (d->text) tb_crash(line, tb_cat(\"в dict нет ключа: \", *(const char * const *)k));\n"; *(const char * *)tb_grow(v_lines) = tb_v6505; }
    { const char * tb_v6506 = "        tb_crash(line, tb_cat(\"в dict нет ключа: \", tb_itos(*(const long long *)k)));\n"; *(const char * *)tb_grow(v_lines) = tb_v6506; }
    { const char * tb_v6507 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6507; }
