    { const char * tb_v6531 = "        if (d->mode == 0) __builtin_prefetch(d->keys->data + (s - 1) * d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v6531; }
    { const char * tb_v6532 = "        __builtin_prefetch(d->vals->data + (s - 1) * d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v6532; }
    { const char * tb_v6533 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6533; }
    { const char * tb_v6534 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6534; }
    { const char * tb_v6535 = "// элемент списка заранее (prefetch за пределами списка ничего не ломает)\n"; *(const char * *)tb_grow(v_lines) = tb_v6535; }
    { const char * tb_v6536 = "TB_INL void tb_lpre(tb_list *l, long long i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6536; }
    { const char * tb_v6537 = "    __builtin_prefetch(l->data + i * l->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v6537; }
    { const char * tb_v6538 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6538; }
    { const char * tb_v6539 = "// ---------- холодные качества obj: своя память, отдельно от горячих ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6539; }
    { const char * tb_v6540 = "TB_API void *tb_cold_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6540; }
    { const char * tb_v6541 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v6541; }
