    { const char * tb_v6550 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v6550; }
    { const char * tb_v6551 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6551; }
    { const char * tb_v6552 = "// ---------- obj: память ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6552; }
    { const char * tb_v6553 = "// Внутри temp и шага цикла — из временной памяти, иначе — из памяти с уборкой.\n"; *(const char * *)tb_grow(v_lines) = tb_v6553; }
    { const char * tb_v6554 = "TB_API void *tb_obj_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6554; }
    { const char * tb_v6555 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v6555; }
    { const char * tb_v6556 = "    return tb_gc_alloc(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v6556; }
