    { const char * tb_v6591 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6591; }
    { const char * tb_v6592 = "TB_API tb_dict *tb_dict_from(int text, long long vsize, long long n, const void *keys, const void *vals) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6592; }
    { const char * tb_v6593 = "    tb_dict *d = tb_dict_new(text, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v6593; }
