    { const char * tb_v6600 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v6600; }
    { const char * tb_v6601 = "// ---------- on all cores: цикл на всех ядрах ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6601; }
    { const char * tb_v6602 = "// Работа делится на куски; каждое ядро берёт следующий свободный кусок,\n"; *(const char * *)tb_grow(v_lines) = tb_v6602; }
    { const char * tb_v6603 = "// пока они не кончатся (так ядра не простаивают, если куски разные по тяжести).\n"; *(const char * *)tb_grow(v_lines) = tb_v6603; }
    { const char * tb_v6604 = "// shared: каждое ядро копит своё на «листке», потом один раз добавляет под замком.\n"; *(const char * *)tb_grow(v_lines) = tb_v6604; }
    { const char * tb_v6605 = "TB_API pthread_mutex_t tb_par_lock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v6605; }
    { const char * tb_v6606 = "TB_API int tb_cores(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6606; }
    { const char * tb_v6607 = "    const char *want = getenv(\"TB_CORES\");   // TB_CORES=1 — проверить на одном ядре\n"; *(const char * *)tb_grow(v_lines) = tb_v6607; }
    { const char * tb_v6608 = "    long n = want != 0 ? atol(want) : sysconf(_SC_NPROCESSORS_ONLN);\n"; *(const char * *)tb_grow(v_lines) = tb_v6608; }
