    { const char * tb_v6611 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v6611; }
    { const char * tb_v6612 = "TB_API void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6612; }
    { const char * tb_v6613 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v6613; }
