    { const char * tb_v6623 = "// Готовые потоки: создаются один раз (при первом on all cores) и ждут работу.\n"; *(const char * *)tb_grow(v_lines) = tb_v6623; }
    { const char * tb_v6624 = "// Раньше каждый цикл на ядрах создавал и закрывал потоки — для коротких циклов это было дольше самой работы.\n"; *(const char * *)tb_grow(v_lines) = tb_v6624; }
    { const char * tb_v6625 = "TB_API pthread_mutex_t tb_pool_m = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v6625; }
    { const char * tb_v6626 = "TB_API pthread_cond_t tb_pool_go = PTHREAD_COND_INITIALIZER, tb_pool_end = PTHREAD_COND_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v6626; }
    { const char * tb_v6627 = "TB_API int tb_pool_n = 0, tb_pool_want = 0, tb_pool_busy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6627; }
    { const char * tb_v6628 = "TB_API volatile long long tb_pool_gen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6628; }
    { const char * tb_v6629 = "TB_API volatile int tb_pool_left = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6629; }
    { const char * tb_v6630 = "TB_API void *(*tb_pool_work)(void *) = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6630; }
    { const char * tb_v6631 = "TB_API void *tb_pool_job = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6631; }
    { const char * tb_v6632 = "TB_API void *tb_pool_loop(void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6632; }
    { const char * tb_v6633 = "    int me = (int)(long long)arg;\n"; *(const char * *)tb_grow(v_lines) = tb_v6633; }
    { const char * tb_v6634 = "    // поток пула не считается «работающим», пока ждёт: уборка памяти может идти\n"; *(const char * *)tb_grow(v_lines) = tb_v6634; }
    { const char * tb_v6635 = "    __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v6635; }
    { const char * tb_v6636 = "    long long seen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6636; }
    { const char * tb_v6637 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6637; }
    { const char * tb_v6638 = "        // немного ждём без сна: циклы на ядрах часто идут один за другим\n"; *(const char * *)tb_grow(v_lines) = tb_v6638; }
    { const char * tb_v6639 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_gen, __ATOMIC_ACQUIRE) == seen; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v6639; }
    { const char * tb_v6640 = "            __builtin_ia32_pause_or_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v6640; }
    { const char * tb_v6641 = "        pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v6641; }
    { const char * tb_v6642 = "        while (tb_pool_gen == seen) pthread_cond_wait(&tb_pool_go, &tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v6642; }
    { const char * tb_v6643 = "        seen = tb_pool_gen;\n"; *(const char * *)tb_grow(v_lines) = tb_v6643; }
    { const char * tb_v6644 = "        int mine = me < tb_pool_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v6644; }
    { const char * tb_v6645 = "        void *(*work)(void *) = tb_pool_work;\n"; *(const char * *)tb_grow(v_lines) = tb_v6645; }
    { const char * tb_v6646 = "        void *job = tb_pool_job;\n"; *(const char * *)tb_grow(v_lines) = tb_v6646; }
    { const char * tb_v6647 = "        pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v6647; }
    { const char * tb_v6648 = "        if (!mine) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v6648; }
    { const char * tb_v6649 = "        work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v6649; }
    { const char * tb_v6650 = "        __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v6650; }
    { const char * tb_v6651 = "        if (__atomic_sub_fetch(&tb_pool_left, 1, __ATOMIC_ACQ_REL) == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6651; }
    { const char * tb_v6652 = "            pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v6652; }
    { const char * tb_v6653 = "            pthread_cond_signal(&tb_pool_end);\n"; *(const char * *)tb_grow(v_lines) = tb_v6653; }
    { const char * tb_v6654 = "            pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v6654; }
    { const char * tb_v6655 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6655; }
    { const char * tb_v6656 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6656; }
    { const char * tb_v6657 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6657; }
    { const char * tb_v6658 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6658; }
    { const char * tb_v6659 = "TB_API void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6659; }
    { const char * tb_v6660 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v6660; }
    { const char * tb_v6661 = "    if (n > total) n = (int)total;\n"; *(const char * *)tb_grow(v_lines) = tb_v6661; }
    { const char * tb_v6662 = "    if (n < 1) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6662; }
    { const char * tb_v6663 = "    if (n == 1) { work(job); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6663; }
    { const char * tb_v6664 = "    // пул уже занят (цикл на ядрах из background или изнутри другого) — по-старому, своими потоками\n"; *(const char * *)tb_grow(v_lines) = tb_v6664; }
    { const char * tb_v6665 = "    if (__atomic_exchange_n(&tb_pool_busy, 1, __ATOMIC_ACQ_REL)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6665; }
    { const char * tb_v6666 = "        pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v6666; }
    { const char * tb_v6667 = "        for (int i = 1; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v6667; }
