    { const char * tb_v6893 = "    if (!q) { tb_err = \"grow_mem: не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6893; }
    { const char * tb_v6894 = "    if ((uint64_t)n > old) memset((unsigned char *)(q + 1) + old, 0, (size_t)((uint64_t)n - old));\n"; *(const char * *)tb_grow(v_lines) = tb_v6894; }
    { const char * tb_v6895 = "    q->size = (uint64_t)n;\n"; *(const char * *)tb_grow(v_lines) = tb_v6895; }
    { const char * tb_v6896 = "    return (long long)(uintptr_t)(q + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v6896; }
    { const char * tb_v6897 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6897; }
    { const char * tb_v6898 = "// copy_mem(куда, откуда, байт): блоки могут перекрываться\n"; *(const char * *)tb_grow(v_lines) = tb_v6898; }
    { const char * tb_v6899 = "TB_API void tb_copy_mem(long long dst, long long src, long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6899; }
    { const char * tb_v6900 = "    if (n < 0) tb_crash(line, \"copy_mem: число байт меньше нуля\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6900; }
    { const char * tb_v6901 = "    if (n == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6901; }
    { const char * tb_v6902 = "    if (tb_memchk()) { tb_mem_touch((uintptr_t)src, (uint64_t)n, line); tb_mem_touch((uintptr_t)dst, (uint64_t)n, line); }\n"; *(const char * *)tb_grow(v_lines) = tb_v6902; }
    { const char * tb_v6903 = "    memmove((void *)(uintptr_t)dst, (const void *)(uintptr_t)src, (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v6903; }
    { const char * tb_v6904 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6904; }
    { const char * tb_v6905 = "// ---------- use c: функции из C ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6905; }
    { const char * tb_v6906 = "// настоящее имя функции C (на Mac у имён в библиотеке спереди _)\n"; *(const char * *)tb_grow(v_lines) = tb_v6906; }
    { const char * tb_v6907 = "#ifdef __APPLE__\n"; *(const char * *)tb_grow(v_lines) = tb_v6907; }
    { const char * tb_v6908 = "#define TB_CSYM(s) __asm__(\"_\" s)\n"; *(const char * *)tb_grow(v_lines) = tb_v6908; }
    { const char * tb_v6909 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v6909; }
    { const char * tb_v6910 = "#define TB_CSYM(s) __asm__(s)\n"; *(const char * *)tb_grow(v_lines) = tb_v6910; }
    { const char * tb_v6911 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v6911; }
    { const char * tb_v6912 = "// текст из C: копия в память Tachbit (C может потом поменять или отдать свой); NULL → \"\"\n"; *(const char * *)tb_grow(v_lines) = tb_v6912; }
    { const char * tb_v6913 = "TB_API const char *tb_ctext(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6913; }
    { const char * tb_v6914 = "    if (!p) return \"\";\n"; *(const char * *)tb_grow(v_lines) = tb_v6914; }
    { const char * tb_v6915 = "    size_t n = strlen(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v6915; }
    { const char * tb_v6916 = "    char *s = tb_tmem(n + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v6916; }
    { const char * tb_v6917 = "    memcpy(s, p, n + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v6917; }
    { const char * tb_v6918 = "    return s;\n"; *(const char * *)tb_grow(v_lines) = tb_v6918; }
    { const char * tb_v6919 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6919; }
    { const char * tb_v6920 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v6920; }
    { const char * tb_v6921 = "// ---------- zone: область памяти. Много кусков берутся быстро и освобождаются разом ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6921; }
    { const char * tb_v6922 = "// Зона — цепочка больших кусков. zone_take отрезает от текущего куска (16 байт выравнивание, нули),\n"; *(const char * *)tb_grow(v_lines) = tb_v6922; }
    { const char * tb_v6923 = "// кончился кусок — берёт новый. zone_clear отдаёт всё, кроме первого куска; zone_free — всё.\n"; *(const char * *)tb_grow(v_lines) = tb_v6923; }
    { const char * tb_v6924 = "#define TB_ZONE_LIVE 0x5A4F4E454C495645ULL\n"; *(const char * *)tb_grow(v_lines) = tb_v6924; }
    { const char * tb_v6925 = "typedef struct tb_zchunk { struct tb_zchunk *next; uint64_t size, used, pad; } tb_zchunk;   // 32 байта: данные с выравниванием 16\n"; *(const char * *)tb_grow(v_lines) = tb_v6925; }
    { const char * tb_v6926 = "typedef struct { uint64_t magic, step; tb_zchunk *first, *cur; } tb_zone;\n"; *(const char * *)tb_grow(v_lines) = tb_v6926; }
    { const char * tb_v6927 = "// данные куска: сразу за заголовком, с выравниванием 16 (malloc в ядре выравнивает меньше)\n"; *(const char * *)tb_grow(v_lines) = tb_v6927; }
    { const char * tb_v6928 = "#define TB_ZDATA(k) ((unsigned char *)(((uintptr_t)((k) + 1) + 15) & ~(uintptr_t)15))\n"; *(const char * *)tb_grow(v_lines) = tb_v6928; }
    { const char * tb_v6929 = "static tb_zchunk *tb_zone_chunk(uint64_t n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6929; }
    { const char * tb_v6930 = "    tb_zchunk *k = malloc(sizeof(tb_zchunk) + (size_t)n + 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v6930; }
    { const char * tb_v6931 = "    if (!k) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6931; }
    { const char * tb_v6932 = "    k->next = 0; k->size = n; k->used = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6932; }
    { const char * tb_v6933 = "    memset(TB_ZDATA(k), 0, (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v6933; }
    { const char * tb_v6934 = "    return k;\n"; *(const char * *)tb_grow(v_lines) = tb_v6934; }
    { const char * tb_v6935 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6935; }
    { const char * tb_v6936 = "// zone_new(байт): первый кусок такого размера; дальше куски того же размера (или больше, если нужно)\n"; *(const char * *)tb_grow(v_lines) = tb_v6936; }
    { const char * tb_v6937 = "TB_API long long tb_zone_new(long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6937; }
    { const char * tb_v6938 = "    (void)line;\n"; *(const char * *)tb_grow(v_lines) = tb_v6938; }
    { const char * tb_v6939 = "    if (n <= 0) { tb_err = \"zone_new: размер должен быть больше нуля\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6939; }
    { const char * tb_v6940 = "    if ((unsigned long long)n > ((unsigned long long)1 << 46)) { tb_err = \"zone_new: слишком большой размер\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6940; }
    { const char * tb_v6941 = "    tb_zone *z = malloc(sizeof(tb_zone));\n"; *(const char * *)tb_grow(v_lines) = tb_v6941; }
    { const char * tb_v6942 = "    if (!z) { tb_err = \"zone_new: не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6942; }
    { const char * tb_v6943 = "    uint64_t step = ((uint64_t)n + 15) & ~(uint64_t)15;\n"; *(const char * *)tb_grow(v_lines) = tb_v6943; }
    { const char * tb_v6944 = "    z->first = z->cur = tb_zone_chunk(step);\n"; *(const char * *)tb_grow(v_lines) = tb_v6944; }
    { const char * tb_v6945 = "    if (!z->first) { free(z); tb_err = \"zone_new: не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6945; }
    { const char * tb_v6946 = "    z->magic = TB_ZONE_LIVE; z->step = step;\n"; *(const char * *)tb_grow(v_lines) = tb_v6946; }
    { const char * tb_v6947 = "    return (long long)(uintptr_t)z;\n"; *(const char * *)tb_grow(v_lines) = tb_v6947; }
    { const char * tb_v6948 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6948; }
    { const char * tb_v6949 = "static tb_zone *tb_zone_own(long long a, int line, const char *who) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6949; }
    { const char * tb_v6950 = "    tb_zone *z = (tb_zone *)(uintptr_t)a;\n"; *(const char * *)tb_grow(v_lines) = tb_v6950; }
    { const char * tb_v6951 = "    if (!z || z->magic != TB_ZONE_LIVE) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6951; }
    { const char * tb_v6952 = "        char buf[400];\n"; *(const char * *)tb_grow(v_lines) = tb_v6952; }
    { const char * tb_v6953 = "        snprintf(buf, sizeof buf, \"%s: это не зона из zone_new или она уже освобождена\", who);\n"; *(const char * *)tb_grow(v_lines) = tb_v6953; }
    { const char * tb_v6954 = "        tb_crash(line, buf);\n"; *(const char * *)tb_grow(v_lines) = tb_v6954; }
    { const char * tb_v6955 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6955; }
    { const char * tb_v6956 = "    return z;\n"; *(const char * *)tb_grow(v_lines) = tb_v6956; }
    { const char * tb_v6957 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6957; }
    { const char * tb_v6958 = "// zone_take(зона, байт): адрес нового куска (нули)\n"; *(const char * *)tb_grow(v_lines) = tb_v6958; }
    { const char * tb_v6959 = "TB_API long long tb_zone_take(long long a, long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6959; }
    { const char * tb_v6960 = "    tb_zone *z = tb_zone_own(a, line, \"zone_take\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6960; }
    { const char * tb_v6961 = "    if (n <= 0) tb_crash(line, \"zone_take: размер должен быть больше нуля\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6961; }
    { const char * tb_v6962 = "    uint64_t need = ((uint64_t)n + 15) & ~(uint64_t)15;\n"; *(const char * *)tb_grow(v_lines) = tb_v6962; }
    { const char * tb_v6963 = "    tb_zchunk *k = z->cur;\n"; *(const char * *)tb_grow(v_lines) = tb_v6963; }
    { const char * tb_v6964 = "    if (k->size - k->used < need) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6964; }
    { const char * tb_v6965 = "        if (k->next && k->next->size >= need) k = k->next;\n"; *(const char * *)tb_grow(v_lines) = tb_v6965; }
    { const char * tb_v6966 = "        else {\n"; *(const char * *)tb_grow(v_lines) = tb_v6966; }
    { const char * tb_v6967 = "            tb_zchunk *nk = tb_zone_chunk(need > z->step ? need : z->step);\n"; *(const char * *)tb_grow(v_lines) = tb_v6967; }
    { const char * tb_v6968 = "            if (!nk) tb_crash(line, \"zone_take: не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6968; }
    { const char * tb_v6969 = "            nk->next = k->next; k->next = nk; k = nk;\n"; *(const char * *)tb_grow(v_lines) = tb_v6969; }
    { const char * tb_v6970 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6970; }
    { const char * tb_v6971 = "        z->cur = k;\n"; *(const char * *)tb_grow(v_lines) = tb_v6971; }
    { const char * tb_v6972 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6972; }
    { const char * tb_v6973 = "    unsigned char *p = TB_ZDATA(k) + k->used;\n"; *(const char * *)tb_grow(v_lines) = tb_v6973; }
    { const char * tb_v6974 = "    k->used += need;\n"; *(const char * *)tb_grow(v_lines) = tb_v6974; }
    { const char * tb_v6975 = "    return (long long)(uintptr_t)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v6975; }
    { const char * tb_v6976 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6976; }
    { const char * tb_v6977 = "// zone_clear(зона): всё взятое больше не нужно; первый кусок остаётся для новых zone_take\n"; *(const char * *)tb_grow(v_lines) = tb_v6977; }
    { const char * tb_v6978 = "TB_API void tb_zone_clear(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6978; }
    { const char * tb_v6979 = "    tb_zone *z = tb_zone_own(a, line, \"zone_clear\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6979; }
    { const char * tb_v6980 = "    tb_zchunk *k = z->first->next;\n"; *(const char * *)tb_grow(v_lines) = tb_v6980; }
    { const char * tb_v6981 = "    while (k) { tb_zchunk *nx = k->next; free(k); k = nx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6981; }
    { const char * tb_v6982 = "    z->first->next = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6982; }
    { const char * tb_v6983 = "    memset(TB_ZDATA(z->first), 0, (size_t)z->first->used);\n"; *(const char * *)tb_grow(v_lines) = tb_v6983; }
    { const char * tb_v6984 = "    z->first->used = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6984; }
    { const char * tb_v6985 = "    z->cur = z->first;\n"; *(const char * *)tb_grow(v_lines) = tb_v6985; }
    { const char * tb_v6986 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6986; }
    { const char * tb_v6987 = "// zone_free(зона): отдать всё; zone_free(0) ничего не делает\n"; *(const char * *)tb_grow(v_lines) = tb_v6987; }
    { const char * tb_v6988 = "TB_API void tb_zone_free(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6988; }
    { const char * tb_v6989 = "    if (a == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v6989; }
    { const char * tb_v6990 = "    tb_zone *z = tb_zone_own(a, line, \"zone_free\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6990; }
    { const char * tb_v6991 = "    tb_zchunk *k = z->first;\n"; *(const char * *)tb_grow(v_lines) = tb_v6991; }
    { const char * tb_v6992 = "    while (k) { tb_zchunk *nx = k->next; free(k); k = nx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6992; }
    { const char * tb_v6993 = "    z->magic = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6993; }
    { const char * tb_v6994 = "    free(z);\n"; *(const char * *)tb_grow(v_lines) = tb_v6994; }
    { const char * tb_v6995 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6995; }
    { const char * tb_v6996 = "// zone_used(зона): сколько байт взято (с выравниванием)\n"; *(const char * *)tb_grow(v_lines) = tb_v6996; }
    { const char * tb_v6997 = "TB_API long long tb_zone_used(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6997; }
    { const char * tb_v6998 = "    tb_zone *z = tb_zone_own(a, line, \"zone_used\");\n"; *(const char * *)tb_grow(v_lines) = tb_v6998; }
    { const char * tb_v6999 = "    long long s = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6999; }
    { const char * tb_v7000 = "    for (tb_zchunk *k = z->first; k; k = k->next) s += (long long)k->used;\n"; *(const char * *)tb_grow(v_lines) = tb_v7000; }
    { const char * tb_v7001 = "    return s;\n"; *(const char * *)tb_grow(v_lines) = tb_v7001; }
    { const char * tb_v7002 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7002; }
    { const char * tb_v7003 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v7003; }
    { const char * tb_v7004 = "// ---------- syscall(номер, ...): прямой вызов ядра ОС (Linux, Mac). Ответ -1 → -номер ошибки ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v7004; }
    { const char * tb_v7005 = "#if !defined(TB_BARE) && !defined(_WIN32)\n"; *(const char * *)tb_grow(v_lines) = tb_v7005; }
    { const char * tb_v7006 = "#include <sys/syscall.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v7006; }
    { const char * tb_v7007 = "#include <errno.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v7007; }
    { const char * tb_v7008 = "#ifdef __APPLE__\n"; *(const char * *)tb_grow(v_lines) = tb_v7008; }
    { const char * tb_v7009 = "#pragma clang diagnostic push\n"; *(const char * *)tb_grow(v_lines) = tb_v7009; }
    { const char * tb_v7010 = "#pragma clang diagnostic ignored \"-Wdeprecated-declarations\"\n"; *(const char * *)tb_grow(v_lines) = tb_v7010; }
    { const char * tb_v7011 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v7011; }
    { const char * tb_v7012 = "TB_API long long tb_syscall(long long n, long long a, long long b, long long c, long long d, long long e, long long f, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7012; }
    { const char * tb_v7013 = "    (void)line;\n"; *(const char * *)tb_grow(v_lines) = tb_v7013; }
    { const char * tb_v7014 = "    long r = syscall((long)n, (long)a, (long)b, (long)c, (long)d, (long)e, (long)f);\n"; *(const char * *)tb_grow(v_lines) = tb_v7014; }
    { const char * tb_v7015 = "    if (r == -1) return -(long long)errno;\n"; *(const char * *)tb_grow(v_lines) = tb_v7015; }
    { const char * tb_v7016 = "    return (long long)r;\n"; *(const char * *)tb_grow(v_lines) = tb_v7016; }
    { const char * tb_v7017 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7017; }
    { const char * tb_v7018 = "#ifdef __APPLE__\n"; *(const char * *)tb_grow(v_lines) = tb_v7018; }
    { const char * tb_v7019 = "#pragma clang diagnostic pop\n"; *(const char * *)tb_grow(v_lines) = tb_v7019; }
    { const char * tb_v7020 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v7020; }
    { const char * tb_v7021 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v7021; }
    { const char * tb_v7022 = "TB_API long long tb_syscall(long long n, long long a, long long b, long long c, long long d, long long e, long long f, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7022; }
    { const char * tb_v7023 = "    (void)n; (void)a; (void)b; (void)c; (void)d; (void)e; (void)f;\n"; *(const char * *)tb_grow(v_lines) = tb_v7023; }
    { const char * tb_v7024 = "    tb_crash(line, \"syscall есть только на Linux и Mac\");\n"; *(const char * *)tb_grow(v_lines) = tb_v7024; }
    { const char * tb_v7025 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7025; }
    { const char * tb_v7026 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7026; }
    { const char * tb_v7027 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v7027; }
    { const char * tb_v7028 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v7028; }
    { const char * tb_v7029 = "// ---------- shape: поля с размером прямо в памяти (регистры, заголовки пакетов) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v7029; }
    { const char * tb_v7030 = "// k = смещение × 2^20 + байт (1, 2, 4, 8; 0 — bytes: отдать адрес) + 16 со знаком + 32 big\n"; *(const char * *)tb_grow(v_lines) = tb_v7030; }
    { const char * tb_v7031 = "//     + 64 × первый бит + 4096 × сколько бит (0 — поле целиком).\n"; *(const char * *)tb_grow(v_lines) = tb_v7031; }
    { const char * tb_v7032 = "// Поле читается и пишется одним volatile-доступом своей ширины: регистр u32 — одной 32-битной операцией.\n"; *(const char * *)tb_grow(v_lines) = tb_v7032; }
    { const char * tb_v7033 = "static inline uint64_t tb_shape_raw(uintptr_t p, int nb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7033; }
    { const char * tb_v7034 = "    if (nb == 1) return *(volatile uint8_t *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v7034; }
    { const char * tb_v7035 = "    if (nb == 2) return *(volatile uint16_t *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v7035; }
    { const char * tb_v7036 = "    if (nb == 4) return *(volatile uint32_t *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v7036; }
