    { const char * tb_v7426 = "// короткий щелчок (касание тачпада): нажали и отпустили между двумя кадрами — mouse_down() всё равно разок скажет «да»\n"; *(const char * *)tb_grow(v_lines) = tb_v7426; }
    { const char * tb_v7427 = "TB_API int tb_mtap = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7427; }
    { const char * tb_v7428 = "// колёсико: шагов с прошлого mouse_wheel() (+ вперёд, от себя; − назад); у тачпада шаги дробные — копим\n"; *(const char * *)tb_grow(v_lines) = tb_v7428; }
    { const char * tb_v7429 = "TB_API int tb_wheel = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7429; }
    { const char * tb_v7430 = "// боковые кнопки мыши: [0] назад, [1] вперёд; tap — нажали и отпустили между кадрами\n"; *(const char * *)tb_grow(v_lines) = tb_v7430; }
    { const char * tb_v7431 = "TB_API int tb_mside[2], tb_mside_tap[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v7431; }
    { const char * tb_v7432 = "TB_API void tb_side(int b, int down) { tb_mside[b] = down; if (down) tb_mside_tap[b] = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7432; }
    { const char * tb_v7433 = "TB_API double tb_wheel_f = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7433; }
    { const char * tb_v7434 = "TB_API void tb_wheel_add(double d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7434; }
    { const char * tb_v7435 = "    tb_wheel_f += d;\n"; *(const char * *)tb_grow(v_lines) = tb_v7435; }
    { const char * tb_v7436 = "    int n = (int)tb_wheel_f;\n"; *(const char * *)tb_grow(v_lines) = tb_v7436; }
    { const char * tb_v7437 = "    tb_wheel += n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7437; }
    { const char * tb_v7438 = "    tb_wheel_f -= n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7438; }
    { const char * tb_v7439 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7439; }
    { const char * tb_v7440 = "// буквы, набранные с прошлого typed_text(), в UTF-8 (стрелки, Enter и прочие не буквы не попадают)\n"; *(const char * *)tb_grow(v_lines) = tb_v7440; }
    { const char * tb_v7441 = "TB_API char tb_typed[512];\n"; *(const char * *)tb_grow(v_lines) = tb_v7441; }
    { const char * tb_v7442 = "TB_API int tb_ntyped = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7442; }
    { const char * tb_v7443 = "TB_API char *tb_gfx_clip_get(void);          // свои у каждой системы: текст (malloc) или 0\n"; *(const char * *)tb_grow(v_lines) = tb_v7443; }
    { const char * tb_v7444 = "TB_API void tb_gfx_clip_set(const char *s);\n"; *(const char * *)tb_grow(v_lines) = tb_v7444; }
    { const char * tb_v7445 = "TB_API void tb_gfx_cursor(int k);              // 0 стрелка, 1 рука, 2 текст, 3 двигать, 4 ↔, 5 ↕, 6 ждать, 7 спрятать\n"; *(const char * *)tb_grow(v_lines) = tb_v7445; }
    { const char * tb_v7446 = "TB_API int tb_cursor_want = 0;                 // курсор, который просили до window_open\n"; *(const char * *)tb_grow(v_lines) = tb_v7446; }
    { const char * tb_v7447 = "TB_API void tb_type_cp(unsigned u) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7447; }
    { const char * tb_v7448 = "    if (u < 32 || u == 127 || (u >= 0xF700 && u <= 0xF8FF) || u > 0x10FFFF) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7448; }
    { const char * tb_v7449 = "    if (tb_ntyped + 4 >= (int)sizeof tb_typed) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7449; }
    { const char * tb_v7450 = "    char *o = tb_typed + tb_ntyped;\n"; *(const char * *)tb_grow(v_lines) = tb_v7450; }
    { const char * tb_v7451 = "    if (u < 0x80) { o[0] = (char)u; tb_ntyped += 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7451; }
    { const char * tb_v7452 = "    else if (u < 0x800) { o[0] = (char)(0xC0 | (u >> 6)); o[1] = (char)(0x80 | (u & 63)); tb_ntyped += 2; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7452; }
    { const char * tb_v7453 = "    else if (u < 0x10000) { o[0] = (char)(0xE0 | (u >> 12)); o[1] = (char)(0x80 | ((u >> 6) & 63)); o[2] = (char)(0x80 | (u & 63)); tb_ntyped += 3; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7453; }
    { const char * tb_v7454 = "    else { o[0] = (char)(0xF0 | (u >> 18)); o[1] = (char)(0x80 | ((u >> 12) & 63)); o[2] = (char)(0x80 | ((u >> 6) & 63)); o[3] = (char)(0x80 | (u & 63)); tb_ntyped += 4; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7454; }
    { const char * tb_v7455 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7455; }
    { const char * tb_v7456 = "TB_API void tb_type_utf8(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7456; }
    { const char * tb_v7457 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v7457; }
    { const char * tb_v7458 = "    while (p && *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7458; }
    { const char * tb_v7459 = "        unsigned u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v7459; }
    { const char * tb_v7460 = "        if (u >= 0x80) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7460; }
    { const char * tb_v7461 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7461; }
    { const char * tb_v7462 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v7462; }
    { const char * tb_v7463 = "            while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v7463; }
    { const char * tb_v7464 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7464; }
    { const char * tb_v7465 = "        tb_type_cp(u);\n"; *(const char * *)tb_grow(v_lines) = tb_v7465; }
    { const char * tb_v7466 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7466; }
    { const char * tb_v7467 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7467; }
    { const char * tb_v7468 = "TB_API unsigned char tb_keys[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v7468; }
    { const char * tb_v7469 = "TB_API unsigned char tb_ktap[256];   // клавишу нажали и отпустили между кадрами: key_down() разок скажет «да»\n"; *(const char * *)tb_grow(v_lines) = tb_v7469; }
    { const char * tb_v7470 = "TB_API long long tb_last_frame = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7470; }
    { const char * tb_v7471 = "// клавиши: буквы и цифры — свой код ASCII (A..Z, 0..9), остальные:\n"; *(const char * *)tb_grow(v_lines) = tb_v7471; }
    { const char * tb_v7472 = "enum { TB_K_ENTER = 10, TB_K_ESC = 27, TB_K_SPACE = 32, TB_K_BACK = 8, TB_K_TAB = 9,\n"; *(const char * *)tb_grow(v_lines) = tb_v7472; }
