    { const char * tb_v8195 = "// снимок кадра (что нарисовано сейчас) — новая картинка; потом draw_image рисует её за один раз\n"; *(const char * *)tb_grow(v_lines) = tb_v8195; }
    { const char * tb_v8196 = "TB_API long long tb_screen_image(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8196; }
    { const char * tb_v8197 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v8197; }
    { const char * tb_v8198 = "    if (!tb_px) { tb_err = \"окно ещё не открыто\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8198; }
    { const char * tb_v8199 = "    size_t n = (size_t)tb_gw * tb_gh, need = tb_imgpx_n + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8199; }
