    { const char * tb_v8583 = "typedef struct { uint32_t a, b, c, pad; } tb_gplane_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v8583; }
    { const char * tb_v8584 = "TB_API tb_gplane_t *tb_gplane = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8584; }
    { const char * tb_v8585 = "// 3D с картинкой (mesh_image): у треугольника ещё запись текстуры — плоскости u·W и v·W (по 64 бита)\n"; *(const char * *)tb_grow(v_lines) = tb_v8585; }
    { const char * tb_v8586 = "// и сама картинка; номер записи — в pad его плоскости глубины, а в m ещё бит 29\n"; *(const char * *)tb_grow(v_lines) = tb_v8586; }
    { const char * tb_v8587 = "typedef struct { int64_t au, bu, cu, av, bv, cv; uint32_t off, w, h, pad; } tb_gtex_t;   // 64 байта\n"; *(const char * *)tb_grow(v_lines) = tb_v8587; }
    { const char * tb_v8588 = "enum { TB_GT_CAP = 16384 };\n"; *(const char * *)tb_grow(v_lines) = tb_v8588; }
    { const char * tb_v8589 = "TB_API tb_gtex_t *tb_gtex = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8589; }
    { const char * tb_v8590 = "TB_API int tb_gtn = 0, tb_gpu_tex = 0;   // записей в текущем наборе; видеокарта умеет картинки на сетках\n"; *(const char * *)tb_grow(v_lines) = tb_v8590; }
    { const char * tb_v8591 = "// «новые» треугольники 3D (свет по углам, тени, туман, прозрачность — см. tb_lit_px): у каждого запись — W трёх углов,\n"; *(const char * *)tb_grow(v_lines) = tb_v8591; }
    { const char * tb_v8592 = "// флаги (1 — тени, 2 — туман, прозрачность << 8), по 12 чисел на угол (значение × W), туман, картинка, карта теней.\n"; *(const char * *)tb_grow(v_lines) = tb_v8592; }
    { const char * tb_v8593 = "// Номер записи — в pad плоскости глубины, а в m — бит 28 (и бит 27 у прозрачного)\n"; *(const char * *)tb_grow(v_lines) = tb_v8593; }
    { const char * tb_v8594 = "typedef struct { int32_t w[3], flags; int32_t v[3][12]; int32_t fogc, fogn, fogf, tex, smn, smbase, pad0, pad1; } tb_glit_t;   // 192 байта\n"; *(const char * *)tb_grow(v_lines) = tb_v8594; }
    { const char * tb_v8595 = "enum { TB_GL_CAP = 16384, TB_LV = 11, TB_SM_N = 1024 };\n"; *(const char * *)tb_grow(v_lines) = tb_v8595; }
    { const char * tb_v8596 = "TB_API tb_glit_t *tb_glit = 0;           // записи всех наборов (видны видеокарте; появляются при первом таком треугольнике)\n"; *(const char * *)tb_grow(v_lines) = tb_v8596; }
    { const char * tb_v8597 = "TB_API int tb_gln = 0, tb_gpu_lit = 0;   // записей в текущем наборе; видеокарта умеет такие треугольники\n"; *(const char * *)tb_grow(v_lines) = tb_v8597; }
    { const char * tb_v8598 = "TB_API void tb_gpu_lit_mem(int shadow);  // своя у каждой системы: память записей (0) или карт теней (1)\n"; *(const char * *)tb_grow(v_lines) = tb_v8598; }
    { const char * tb_v8599 = "TB_API void tb_gpu_tril(const long long *t, long long c, const uint32_t *pl, const tb_glit_t *L, const tb_gtex_t *tx);\n"; *(const char * *)tb_grow(v_lines) = tb_v8599; }
    { const char * tb_v8600 = "TB_API int tb_gzclr = 1;               // видеокарта: в начале кадра стереть глубину\n"; *(const char * *)tb_grow(v_lines) = tb_v8600; }
    { const char * tb_v8601 = "TB_API int tb_zclr = 1;                // процессор: то же для tb_zb\n"; *(const char * *)tb_grow(v_lines) = tb_v8601; }
    { const char * tb_v8602 = "TB_API uint32_t *tb_zb = 0;            // процессор: глубина каждой точки\n"; *(const char * *)tb_grow(v_lines) = tb_v8602; }
    { const char * tb_v8603 = "TB_API long long tb_zb_n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8603; }
    { const char * tb_v8604 = "// 3D на видеокарте: сетка один раз ложится в память видеокарты (tb_mesh_pack), а на каждый draw_mesh\n"; *(const char * *)tb_grow(v_lines) = tb_v8604; }
    { const char * tb_v8605 = "// пишется только запись: 3 строки по 4 целых — поворот (камера × поворот сетки) × 2^30 и сдвиг × 4096.\n"; *(const char * *)tb_grow(v_lines) = tb_v8605; }
    { const char * tb_v8606 = "// В пачке фигур это одна особая фигура m = 3: x0 — сетка, y0 — какие грани не видны, x1 — первая запись,\n"; *(const char * *)tb_grow(v_lines) = tb_v8606; }
    { const char * tb_v8607 = "// y1 — сколько записей подряд. Углы, экран и глубину считает видеокарта (tb3.vert) целыми числами —\n"; *(const char * *)tb_grow(v_lines) = tb_v8607; }
    { const char * tb_v8608 = "// той же формулой, что процессор (tb_m3_corner): кадры совпадают точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v8608; }
    { const char * tb_v8609 = "typedef struct { int32_t r[16]; } tb_grec;   // 4 строки: поворот × 2^30 и сдвиг × 4096 (3), свет в сетке (x, y, z × 2^14, фон × 256; фон -1 — без света)\n"; *(const char * *)tb_grow(v_lines) = tb_v8609; }
    { const char * tb_v8610 = "enum { TB_GR_CAP = 65536 };\n"; *(const char * *)tb_grow(v_lines) = tb_v8610; }
    { const char * tb_v8611 = "TB_API tb_grec *tb_grec_p = 0;         // записи всех наборов подряд (видны видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v8611; }
    { const char * tb_v8612 = "TB_API int tb_grn = 0;                 // сколько записей в текущем наборе\n"; *(const char * *)tb_grow(v_lines) = tb_v8612; }
    { const char * tb_v8613 = "TB_API int tb_gpu_mesh = 0;            // 1: видеокарта умеет считать сетки сама (конвейер собрался)\n"; *(const char * *)tb_grow(v_lines) = tb_v8613; }
    { const char * tb_v8614 = "TB_API int tb_mesh_gdirty = 1;         // сетки поменялись: перед рисованием залить заново\n"; *(const char * *)tb_grow(v_lines) = tb_v8614; }
    { const char * tb_v8615 = "TB_API long long tb_gbatch = 1;        // номер текущей пачки (растёт после каждой отдачи видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v8615; }
    { const char * tb_v8616 = "typedef struct { float size[2]; int32_t tbase, ntri, rbase, f, gw, gh, cull; } tb_gpc;   // постоянные шейдера сеток\n"; *(const char * *)tb_grow(v_lines) = tb_v8616; }
    { const char * tb_v8617 = "TB_API long long tb_mesh_pack(int32_t *dst);   // все сетки подряд для видеокарты (dst = 0: только размер)\n"; *(const char * *)tb_grow(v_lines) = tb_v8617; }
    { const char * tb_v8618 = "TB_API void tb_mesh_gpc(const tb_ginst *g, int slot, tb_gpc *pc);   // постоянные для фигуры m = 3\n"; *(const char * *)tb_grow(v_lines) = tb_v8618; }
    { const char * tb_v8619 = "// TB_GSLOTS наборов памяти по кругу: пока видеокарта рисует один кадр, программа уже пишет следующий\n"; *(const char * *)tb_grow(v_lines) = tb_v8619; }
    { const char * tb_v8620 = "enum { TB_GSLOTS = 3 };\n"; *(const char * *)tb_grow(v_lines) = tb_v8620; }
    { const char * tb_v8621 = "TB_API int tb_gslot = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8621; }
    { const char * tb_v8622 = "TB_API uint32_t *tb_gpu_back = 0;      // TB_GPU_CHECK: кадр, прочитанный обратно с видеокарты\n"; *(const char * *)tb_grow(v_lines) = tb_v8622; }
    { const char * tb_v8623 = "TB_API long long tb_gpu_frames = 0, tb_gpu_bad = 0, tb_gpu_shskip = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8623; }
    { const char * tb_v8624 = "TB_API void tb_gpu_flush(int present);   // своя у каждой системы: Metal или Vulkan\n"; *(const char * *)tb_grow(v_lines) = tb_v8624; }
    { const char * tb_v8625 = "TB_API void tb_gpu_vsync(void);          // включить или выключить ожидание экрана (tb_gpu_nosync)\n"; *(const char * *)tb_grow(v_lines) = tb_v8625; }
    { const char * tb_v8626 = "TB_API int tb_gpu_nosync = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8626; }
    { const char * tb_v8627 = "TB_API int tb_gpu_resize(int ow, int oh);   // окно поменяло размер\n"; *(const char * *)tb_grow(v_lines) = tb_v8627; }
    { const char * tb_v8628 = "// окно можно тянуть мышью, если программа спросила его размер (window_w, window_h)\n"; *(const char * *)tb_grow(v_lines) = tb_v8628; }
    { const char * tb_v8629 = "TB_API int tb_resizable = 0, tb_new_w = 0, tb_new_h = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8629; }
    { const char * tb_v8630 = "// несколько окон (1.3): номер текущего окна, сколько мест занято, ручка каждого окна в системе\n"; *(const char * *)tb_grow(v_lines) = tb_v8630; }
    { const char * tb_v8631 = "#define TB_WMAX 16\n"; *(const char * *)tb_grow(v_lines) = tb_v8631; }
    { const char * tb_v8632 = "TB_API int tb_wcur = 0, tb_wn = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8632; }
    { const char * tb_v8633 = "TB_API uintptr_t tb_whand[TB_WMAX];\n"; *(const char * *)tb_grow(v_lines) = tb_v8633; }
    { const char * tb_v8634 = "TB_API int tb_wfind(uintptr_t h);\n"; *(const char * *)tb_grow(v_lines) = tb_v8634; }
    { const char * tb_v8635 = "TB_API void tb_wswitch(int i);\n"; *(const char * *)tb_grow(v_lines) = tb_v8635; }
    { const char * tb_v8636 = "TB_API void tb_wmark_closed(int i);\n"; *(const char * *)tb_grow(v_lines) = tb_v8636; }
    { const char * tb_v8637 = "// полный экран и мышь для шутера (1.3): сдвиг мыши с прошлого mouse_dx/mouse_dy, мышь захвачена\n"; *(const char * *)tb_grow(v_lines) = tb_v8637; }
    { const char * tb_v8638 = "TB_API double tb_mdx = 0, tb_mdy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8638; }
    { const char * tb_v8639 = "TB_API int tb_mlock = 0, tb_mseen = 0, tb_mwarp = 0, tb_cursor_prog = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8639; }
    { const char * tb_v8640 = "TB_API void tb_gfx_fullscreen(int on);   // свои у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v8640; }
    { const char * tb_v8641 = "TB_API void tb_gfx_lock(int on);\n"; *(const char * *)tb_grow(v_lines) = tb_v8641; }
    { const char * tb_v8642 = "// мышь в точке (x, y) окна: копим сдвиг. Захвачена — меряем от середины окна, мышь потом вернётся туда\n"; *(const char * *)tb_grow(v_lines) = tb_v8642; }
    { const char * tb_v8643 = "TB_API void tb_mouse_at(int x, int y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8643; }
    { const char * tb_v8644 = "    if (tb_mlock) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8644; }
    { const char * tb_v8645 = "        int cx = tb_gw / 2, cy = tb_gh / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v8645; }
    { const char * tb_v8646 = "        if (x == cx && y == cy) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8646; }
    { const char * tb_v8647 = "        tb_mdx += x - cx; tb_mdy += y - cy; tb_mwarp = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8647; }
    { const char * tb_v8648 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8648; }
    { const char * tb_v8649 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8649; }
    { const char * tb_v8650 = "    if (tb_mseen) { tb_mdx += x - tb_mx; tb_mdy += y - tb_my; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8650; }
    { const char * tb_v8651 = "    tb_mseen = 1; tb_mx = x; tb_my = y;\n"; *(const char * *)tb_grow(v_lines) = tb_v8651; }
    { const char * tb_v8652 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8652; }
    { const char * tb_v8653 = "TB_API int tb_sharp = 0;       // window_sharp(): окно в настоящих точках экрана\n"; *(const char * *)tb_grow(v_lines) = tb_v8653; }
    { const char * tb_v8654 = "TB_API double tb_sc = 1;        // во сколько раз точек больше (Retina — 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v8654; }
    { const char * tb_v8655 = "TB_API void tb_gfx_resizable(void);   // свои у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v8655; }
    { const char * tb_v8656 = "TB_API void tb_gfx_reimage(void);            // 1: не ждать обновления экрана (set_fps(0), TB_FPS_FREE=1)\n"; *(const char * *)tb_grow(v_lines) = tb_v8656; }
    { const char * tb_v8657 = "TB_API int tb_gpu_want(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8657; }
    { const char * tb_v8658 = "    const char *e = getenv(\"TB_GPU\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8658; }
    { const char * tb_v8659 = "    tb_gpu_check = getenv(\"TB_GPU_CHECK\") != 0 && getenv(\"TB_GPU_CHECK\")[0] == '1';\n"; *(const char * *)tb_grow(v_lines) = tb_v8659; }
    { const char * tb_v8660 = "    if (getenv(\"TB_FPS_FREE\")) tb_gpu_nosync = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8660; }
    { const char * tb_v8661 = "    return !(e && e[0] == '0');\n"; *(const char * *)tb_grow(v_lines) = tb_v8661; }
    { const char * tb_v8662 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8662; }
    { const char * tb_v8663 = "TB_API void tb_gpu_say(const char *what) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8663; }
    { const char * tb_v8664 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v8664; }
    { const char * tb_v8665 = "    if ((e && e[0] == '1') || tb_gpu_check) fprintf(stderr, tb_tr(\"окно: рисует %s\\n\"), what);\n"; *(const char * *)tb_grow(v_lines) = tb_v8665; }
    { const char * tb_v8666 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8666; }
    { const char * tb_v8667 = "TB_API void tb_gpu_report(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8667; }
    { const char * tb_v8668 = "    fprintf(stderr, tb_tr(\"TB_GPU_CHECK: кадров %lld, разошлось %lld\\n\"), tb_gpu_frames, tb_gpu_bad);\n"; *(const char * *)tb_grow(v_lines) = tb_v8668; }
    { const char * tb_v8669 = "    if (tb_gpu_shskip) fprintf(stderr, tb_tr(\"TB_GPU_CHECK: кадров со своими шейдерами (не сверялись): %lld\\n\"), tb_gpu_shskip);\n"; *(const char * *)tb_grow(v_lines) = tb_v8669; }
    { const char * tb_v8670 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8670; }
    { const char * tb_v8671 = "// ---- gpu func (1.3): шейдеры программы — их собрал компилятор Tachbit из gpu func ----\n"; *(const char * *)tb_grow(v_lines) = tb_v8671; }
    { const char * tb_v8672 = "// У каждого: имя, вид (0 — углы, 1 — точка), функция для процессора, SPIR-V, имена настроек по порядку.\n"; *(const char * *)tb_grow(v_lines) = tb_v8672; }
    { const char * tb_v8673 = "// Metal берёт все шейдеры из одного текста tb_sh_msl. Сетка со своим шейдером рисуется обычными\n"; *(const char * *)tb_grow(v_lines) = tb_v8673; }
    { const char * tb_v8674 = "// дробными числами (не точка в точку с процессором): в пачке это фигура m = 7 — x0 номер записи,\n"; *(const char * *)tb_grow(v_lines) = tb_v8674; }
    { const char * tb_v8675 = "// y0 шейдер углов, x1 шейдер точки, y1 сколько углов; углы сетки лежат в своём буфере видеокарты\n"; *(const char * *)tb_grow(v_lines) = tb_v8675; }
    { const char * tb_v8676 = "// R — своя запись draw_mesh (лампы, картинки, тени), T — точки всех картинок (tb_imgpx), S — карты теней (tb_shm)\n"; *(const char * *)tb_grow(v_lines) = tb_v8676; }
    { const char * tb_v8677 = "typedef void (*tb_shfn)(const float *R, const uint32_t *T, const uint32_t *S, float *io);\n"; *(const char * *)tb_grow(v_lines) = tb_v8677; }
    { const char * tb_v8678 = "// Вид 2 — шейдер экрана (screen_shader): функция (io, кадр, глубина), в пачке фигура m = 8 — x0 номер записи, x1 шейдер;\n"; *(const char * *)tb_grow(v_lines) = tb_v8678; }
    { const char * tb_v8679 = "// вид 3 — вершины для экрана (один треугольник на всё окно). sv — настройки шейдера экрана (screen_set)\n"; *(const char * *)tb_grow(v_lines) = tb_v8679; }
    { const char * tb_v8680 = "typedef void (*tb_scrfn)(const float *R, const uint32_t *T, const uint32_t *S, float *io, const uint32_t *scr, const float *scz);\n"; *(const char * *)tb_grow(v_lines) = tb_v8680; }
    { const char * tb_v8681 = "typedef struct { const char *name; int stage; tb_shfn fn; const uint32_t *spv; size_t bytes; int nsets; char sets[8][32]; float sv[8]; } tb_shader_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v8681; }
    { const char * tb_v8682 = "enum { TB_SH_MAX = 64, TB_SHR_CAP = 4096, TB_SHR_N = 224, TB_SHB_CAP = 12 * 32768 };   // TB_SHB_CAP — числа матриц костей на набор\n"; *(const char * *)tb_grow(v_lines) = tb_v8682; }
    { const char * tb_v8683 = "TB_API tb_shader_t tb_shaders[TB_SH_MAX];\n"; *(const char * *)tb_grow(v_lines) = tb_v8683; }
    { const char * tb_v8684 = "TB_API int tb_nshaders = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8684; }
    { const char * tb_v8685 = "TB_API const char *tb_sh_msl = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8685; }
    { const char * tb_v8686 = "TB_API float *tb_shrecs = 0;          // записи текущего набора: TB_SHR_N чисел на draw_mesh\n"; *(const char * *)tb_grow(v_lines) = tb_v8686; }
    { const char * tb_v8687 = "TB_API int tb_shrn = 0;            // сколько записей в текущем наборе\n"; *(const char * *)tb_grow(v_lines) = tb_v8687; }
    { const char * tb_v8688 = "TB_API float *tb_shbones = 0;      // матрицы костей текущего набора (после всех записей в том же буфере)\n"; *(const char * *)tb_grow(v_lines) = tb_v8688; }
    { const char * tb_v8689 = "TB_API long long tb_shbn = 0, tb_shbase = 0;   // сколько чисел занято; где они начинаются в буфере (номер числа)\n"; *(const char * *)tb_grow(v_lines) = tb_v8689; }
    { const char * tb_v8690 = "#define TB_SHB_AT(map) do { tb_shbase = (long long)TB_SHR_N * TB_SHR_CAP * TB_GSLOTS + (long long)tb_gslot * TB_SHB_CAP; tb_shbones = (map) + tb_shbase; tb_shbn = 0; } while (0)\n"; *(const char * *)tb_grow(v_lines) = tb_v8690; }
    { const char * tb_v8691 = "TB_API int tb_sh_frame = 0;        // в кадре была сетка со своим шейдером: TB_GPU_CHECK кадр не сверяет\n"; *(const char * *)tb_grow(v_lines) = tb_v8691; }
    { const char * tb_v8692 = "TB_API void tb_sh_lib(const char *msl) { tb_sh_msl = msl; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8692; }
    { const char * tb_v8693 = "TB_API void tb_sh_reg(const char *name, int stage, tb_shfn fn, const uint32_t *spv, size_t bytes, const char *sets) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8693; }
