    { const char * tb_v8764 = "                if (g->x0 == x1) { g->x0 = (int32_t)x0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8764; }
    { const char * tb_v8765 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v8765; }
