    { const char * tb_v8797 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8797; }
    { const char * tb_v8798 = "// картинка с настоящей прозрачностью (буквы шрифта): видеокарта смешивает с тем, что уже нарисовано\n"; *(const char * *)tb_grow(v_lines) = tb_v8798; }
    { const char * tb_v8799 = "TB_API void tb_gpu_image_a(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8799; }
