    { const char * tb_v8819 = "// треугольник сетки с картинкой: плоскость глубины и запись текстуры; m = 2 | бит 29 | (место << 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v8819; }
    { const char * tb_v8820 = "// какой конвейер у фигуры: 0 — 2D, 1 — 3D (глубина), 2 — 3D с картинкой\n"; *(const char * *)tb_grow(v_lines) = tb_v8820; }
    { const char * tb_v8821 = "// 3 — «новый» треугольник, 4 — он же прозрачный (глубину не пишет)\n"; *(const char * *)tb_grow(v_lines) = tb_v8821; }
    { const char * tb_v8822 = "TB_INL int tb_gkind(uint32_t m) { return (m & 0xC0000003u) != 2u ? 0 : (m >> 28) & 1u ? 3 + (int)((m >> 27) & 1u) : (m >> 29) & 1u ? 2 : 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8822; }
    { const char * tb_v8823 = "TB_API void tb_gpu_tri3t(const long long *t, long long c, const uint32_t *pl, const tb_gtex_t *tx) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8823; }
    { const char * tb_v8824 = "    if (tb_gin == TB_GI_CAP || tb_gtn == TB_GT_CAP) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v8824; }
    { const char * tb_v8825 = "    uint32_t at = (uint32_t)(tb_gslot * TB_GI_CAP + tb_gin), gt = (uint32_t)(tb_gslot * TB_GT_CAP + tb_gtn++);\n"; *(const char * *)tb_grow(v_lines) = tb_v8825; }
    { const char * tb_v8826 = "    tb_gplane_t *g = &tb_gplane[at];\n"; *(const char * *)tb_grow(v_lines) = tb_v8826; }
    { const char * tb_v8827 = "    g->a = pl[0]; g->b = pl[1]; g->c = pl[2]; g->pad = gt;\n"; *(const char * *)tb_grow(v_lines) = tb_v8827; }
    { const char * tb_v8828 = "    tb_gtex[gt] = *tx;\n"; *(const char * *)tb_grow(v_lines) = tb_v8828; }
    { const char * tb_v8829 = "    tb_gpu_add(t[0], t[1], t[2], t[3], t[4], t[5], (uint32_t)c & 0xFFFFFF, 2u | (1u << 29) | (at << 2));\n"; *(const char * *)tb_grow(v_lines) = tb_v8829; }
    { const char * tb_v8830 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8830; }
    { const char * tb_v8831 = "TB_API void tb_gpu_glyph(long long x, long long y, int g, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8831; }
    { const char * tb_v8832 = "    if (x >= tb_gw || y >= tb_gh || x + 8 * size <= 0 || y + 16 * size <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8832; }
    { const char * tb_v8833 = "    if (size >= (1 << 22) || x < -(1LL << 30) || y < -(1LL << 30)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8833; }
    { const char * tb_v8834 = "        for (int row = 0; row < 16; row++) for (int col = 0; col < 8; col++)\n"; *(const char * *)tb_grow(v_lines) = tb_v8834; }
    { const char * tb_v8835 = "            if (tb_font[g][row] & (0x80 >> col)) tb_gpu_rect(x + col * size, y + row * size, size, size, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v8835; }
    { const char * tb_v8836 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8836; }
    { const char * tb_v8837 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8837; }
    { const char * tb_v8838 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y;\n"; *(const char * *)tb_grow(v_lines) = tb_v8838; }
    { const char * tb_v8839 = "    long long x1 = x + 8 * size > tb_gw ? tb_gw : x + 8 * size, y1 = y + 16 * size > tb_gh ? tb_gh : y + 16 * size;\n"; *(const char * *)tb_grow(v_lines) = tb_v8839; }
    { const char * tb_v8840 = "    tb_gpu_add(x0, y0, x1, y1, x, y, (uint32_t)c & 0xFFFFFF, (2u << 30) | ((uint32_t)g << 22) | (uint32_t)size);\n"; *(const char * *)tb_grow(v_lines) = tb_v8840; }
    { const char * tb_v8841 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8841; }
    { const char * tb_v8842 = "#if !defined(__APPLE__) && !defined(TB_BARE)\n"; *(const char * *)tb_grow(v_lines) = tb_v8842; }
