    { const char * tb_v11878 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v11878; }
    { const char * tb_v11879 = "TB_API void tb_mouse_irq(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v11879; }
    { const char * tb_v11880 = "    unsigned char st = tb_inb(0x64);\n"; *(const char * *)tb_grow(v_lines) = tb_v11880; }
