    { const char * tb_v11895 = "    if (tb_my >= tb_gh) tb_my = tb_gh - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11895; }
    { const char * tb_v11896 = "    int down = tb_mpk[0] & 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11896; }
    { const char * tb_v11897 = "    if (down && !tb_mdown) tb_mtap = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v11897; }
    { const char * tb_v11898 = "    tb_mdown = down;\n"; *(const char * *)tb_grow(v_lines) = tb_v11898; }
