    { const char * tb_v13799 = "    if (tb_px && x >= 0 && y >= 0 && x < tb_gw && y < tb_gh) tb_px[y * tb_gw + x] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v13799; }
    { const char * tb_v13800 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13800; }
    { const char * tb_v13801 = "// на видеокарте фигуры записываются (tb_gpu_*), на процессоре — рисуются сразу в tb_px.\n"; *(const char * *)tb_grow(v_lines) = tb_v13801; }
    { const char * tb_v13802 = "// TB_GPU_CHECK=1: и то и другое, кадры сверяются\n"; *(const char * *)tb_grow(v_lines) = tb_v13802; }
    { const char * tb_v13803 = "#define TB_CPU_DRAW (!tb_gpu_on || tb_gpu_check)\n"; *(const char * *)tb_grow(v_lines) = tb_v13803; }
    { const char * tb_v13804 = "TB_API long long tb_mdrawn = 0, tb_mdrawn_last = 0;   // сколько draw_mesh дошло до рисования (не отсечено) в кадре\n"; *(const char * *)tb_grow(v_lines) = tb_v13804; }
    { const char * tb_v13805 = "TB_API void tb_clear_window(long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13805; }
    { const char * tb_v13806 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v13806; }
    { const char * tb_v13807 = "    tb_mdrawn_last = tb_mdrawn; tb_mdrawn = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13807; }
