    { const char * tb_v13809 = "    if (tb_gpu_on) { tb_gin = 0; tb_gpu_rect(0, 0, tb_gw, tb_gh, c); }   // всё прежнее закрашено\n"; *(const char * *)tb_grow(v_lines) = tb_v13809; }
    { const char * tb_v13810 = "    if (TB_CPU_DRAW) for (long long i = 0; i < (long long)tb_gw * tb_gh; i++) tb_px[i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v13810; }
    { const char * tb_v13811 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13811; }
    { const char * tb_v13812 = "TB_API void tb_draw_pixel(long long x, long long y, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13812; }
    { const char * tb_v13813 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v13813; }
