    { const char * tb_v13815 = "    if (tb_gpu_on) tb_gpu_rect(x, y, 1, 1, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v13815; }
    { const char * tb_v13816 = "    if (TB_CPU_DRAW) tb_put(x, y, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v13816; }
    { const char * tb_v13817 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13817; }
    { const char * tb_v13818 = "// полупрозрачный цвет (rgba): в старшем байте — прозрачность 1..255 (0 — непрозрачный, как у rgb)\n"; *(const char * *)tb_grow(v_lines) = tb_v13818; }
    { const char * tb_v13819 = "TB_INL uint32_t tb_mix(uint32_t d, uint32_t c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13819; }
    { const char * tb_v13820 = "    uint32_t t = (c >> 24) & 255, a = 255 - t;\n"; *(const char * *)tb_grow(v_lines) = tb_v13820; }
    { const char * tb_v13821 = "    uint32_t rb = ((c & 0xFF00FF) * a + (d & 0xFF00FF) * t + 0x800080) >> 8 & 0xFF00FF;\n"; *(const char * *)tb_grow(v_lines) = tb_v13821; }
    { const char * tb_v13822 = "    uint32_t g = ((c & 0x00FF00) * a + (d & 0x00FF00) * t + 0x008000) >> 8 & 0x00FF00;\n"; *(const char * *)tb_grow(v_lines) = tb_v13822; }
    { const char * tb_v13823 = "    return rb | g;\n"; *(const char * *)tb_grow(v_lines) = tb_v13823; }
