    { const char * tb_v13825 = "TB_API void tb_cpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13825; }
    { const char * tb_v13826 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v13826; }
    { const char * tb_v13827 = "    if ((c >> 24) & 255) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13827; }
    { const char * tb_v13828 = "        for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = tb_mix(tb_px[j * tb_gw + i], (uint32_t)c);\n"; *(const char * *)tb_grow(v_lines) = tb_v13828; }
    { const char * tb_v13829 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13829; }
    { const char * tb_v13830 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v13830; }
    { const char * tb_v13831 = "    for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v13831; }
    { const char * tb_v13832 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13832; }
    { const char * tb_v13833 = "TB_API void tb_draw_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13833; }
    { const char * tb_v13834 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v13834; }
    { const char * tb_v13835 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13835; }
