    { const char * tb_v13846 = "    *p = a >= 255 ? (c & 0xFFFFFF) : tb_mix(*p, ((255 - a) << 24) | (c & 0xFFFFFF));\n"; *(const char * *)tb_grow(v_lines) = tb_v13846; }
    { const char * tb_v13847 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13847; }
    { const char * tb_v13848 = "// draw_shadow(x, y, w, h, r, size, c): мягкая тень скруглённого прямоугольника — внутри цвет c,\n"; *(const char * *)tb_grow(v_lines) = tb_v13848; }
    { const char * tb_v13849 = "// снаружи к size точкам сходит на нет. Корень считается только у кольца и углов, середина — простое смешивание.\n"; *(const char * *)tb_grow(v_lines) = tb_v13849; }
    { const char * tb_v13850 = "TB_API void tb_draw_shadow(long long x, long long y, long long w, long long h, long long r, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13850; }
    { const char * tb_v13851 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v13851; }
    { const char * tb_v13852 = "    if (!tb_px || w <= 0 || h <= 0 || size <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13852; }
    { const char * tb_v13853 = "    if (r * 2 > w) r = w / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v13853; }
    { const char * tb_v13854 = "    if (r * 2 > h) r = h / 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v13854; }
    { const char * tb_v13855 = "    if (tb_gpu_on) {                                   // видеокарта: слоями (без сглаживания)\n"; *(const char * *)tb_grow(v_lines) = tb_v13855; }
    { const char * tb_v13856 = "        for (long long k = size; k > 0; k -= 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13856; }
    { const char * tb_v13857 = "            double f = 1.0 - (double)k / size;\n"; *(const char * *)tb_grow(v_lines) = tb_v13857; }
    { const char * tb_v13858 = "            long long a = (long long)((255 - ((c >> 24) & 255)) * f * f / (size / 2.0) + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v13858; }
    { const char * tb_v13859 = "            if (a > 0) tb_gpu_rect(x - k, y - k + r, w + 2 * k, h + 2 * k - 2 * r, ((255 - a) << 24) | (c & 0xFFFFFF));\n"; *(const char * *)tb_grow(v_lines) = tb_v13859; }
    { const char * tb_v13860 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v13860; }
    { const char * tb_v13861 = "        if (!TB_CPU_DRAW) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v13861; }
    { const char * tb_v13862 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v13862; }
    { const char * tb_v13863 = "    double hw = w / 2.0, hh = h / 2.0, cx = x + hw, cy = y + hh;\n"; *(const char * *)tb_grow(v_lines) = tb_v13863; }
    { const char * tb_v13864 = "    long long y0 = y - size < 0 ? 0 : y - size, y1 = y + h + size > tb_gh ? tb_gh : y + h + size;\n"; *(const char * *)tb_grow(v_lines) = tb_v13864; }
    { const char * tb_v13865 = "    for (long long j = y0; j < y1; j++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13865; }
    { const char * tb_v13866 = "        double py = j + 0.5, dy = fabs(py - cy) - (hh - r);\n"; *(const char * *)tb_grow(v_lines) = tb_v13866; }
    { const char * tb_v13867 = "        if (dy < 0) dy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13867; }
    { const char * tb_v13868 = "        long long xa = x - size < 0 ? 0 : x - size, xb = x + w + size > tb_gw ? tb_gw : x + w + size;\n"; *(const char * *)tb_grow(v_lines) = tb_v13868; }
    { const char * tb_v13869 = "        for (long long i = xa; i < xb; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13869; }
    { const char * tb_v13870 = "            double px = i + 0.5, dx = fabs(px - cx) - (hw - r);\n"; *(const char * *)tb_grow(v_lines) = tb_v13870; }
    { const char * tb_v13871 = "            if (dx < 0) dx = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13871; }
    { const char * tb_v13872 = "            if (dx == 0 && dy == 0) { tb_px[j * tb_gw + i] = tb_mix(tb_px[j * tb_gw + i], (uint32_t)c); continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v13872; }
    { const char * tb_v13873 = "            double d = sqrt(dx * dx + dy * dy) - r;\n"; *(const char * *)tb_grow(v_lines) = tb_v13873; }
    { const char * tb_v13874 = "            if (d >= size) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v13874; }
    { const char * tb_v13875 = "            double f = d <= 0 ? 1 : 1 - d / size;\n"; *(const char * *)tb_grow(v_lines) = tb_v13875; }
    { const char * tb_v13876 = "            tb_cover(i, j, (uint32_t)c, f * f);\n"; *(const char * *)tb_grow(v_lines) = tb_v13876; }
    { const char * tb_v13877 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v13877; }
    { const char * tb_v13878 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v13878; }
    { const char * tb_v13879 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v13879; }
    { const char * tb_v13880 = "// скругление углов: \"\" или \"all\" — все; иначе слова top bottom left right tl tr bl br через пробел\n"; *(const char * *)tb_grow(v_lines) = tb_v13880; }
    { const char * tb_v13881 = "TB_API int tb_corners(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13881; }
    { const char * tb_v13882 = "    if (!s || !*s) return 15;\n"; *(const char * *)tb_grow(v_lines) = tb_v13882; }
    { const char * tb_v13883 = "    int m = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v13883; }
    { const char * tb_v13884 = "    const char *w[] = { \"all\", \"top\", \"bottom\", \"left\", \"right\", \"tl\", \"tr\", \"bl\", \"br\" };\n"; *(const char * *)tb_grow(v_lines) = tb_v13884; }
    { const char * tb_v13885 = "    const int v[] = { 15, 3, 12, 5, 10, 1, 2, 4, 8 };\n"; *(const char * *)tb_grow(v_lines) = tb_v13885; }
    { const char * tb_v13886 = "    while (*s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v13886; }
    { const char * tb_v13887 = "        while (*s == ' ' || *s == ',') s++;\n"; *(const char * *)tb_grow(v_lines) = tb_v13887; }
    { const char * tb_v13888 = "        const char *e = s;\n"; *(const char * *)tb_grow(v_lines) = tb_v13888; }
    { const char * tb_v13889 = "        while (*e && *e != ' ' && *e != ',') e++;\n"; *(const char * *)tb_grow(v_lines) = tb_v13889; }
    { const char * tb_v13890 = "        for (int i = 0; i < 9; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v13890; }
    { const char * tb_v13891 = "            if ((size_t)(e - s) == strlen(w[i]) && strncmp(s, w[i], (size_t)(e - s)) == 0) m |= v[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v13891; }
