    { const char * tb_v13907 = "        tb_gpu_circle(x + r, y + h - 1 - r, r, c); tb_gpu_circle(x + w - 1 - r, y + h - 1 - r, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v13907; }
    { const char * tb_v13908 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v13908; }
