    { const char * tb_v14017 = "TB_API void tb_draw_line(long long x0, long long y0, long long x1, long long y1, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14017; }
    { const char * tb_v14018 = "    TB_SCENE();\n"; *(const char * *)tb_grow(v_lines) = tb_v14018; }
    { const char * tb_v14019 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14019; }
