    { const char * tb_v14435 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14435; }
    { const char * tb_v14436 = "// цвет грани под светом L (x, y, z, фон) — L уже в осях сетки; front — грань смотрит на нас\n"; *(const char * *)tb_grow(v_lines) = tb_v14436; }
    { const char * tb_v14437 = "// (со спины свет считается от обратной стороны: у пола и листа обе стороны освещены честно)\n"; *(const char * *)tb_grow(v_lines) = tb_v14437; }
    { const char * tb_v14438 = "TB_INL uint32_t tb_shade(uint32_t c, const int32_t *n, const int32_t *L, int front) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14438; }
    { const char * tb_v14439 = "    if (L[3] < 0) return c;\n"; *(const char * *)tb_grow(v_lines) = tb_v14439; }
    { const char * tb_v14440 = "    int s = n[0] * L[0] + n[1] * L[1] + n[2] * L[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v14440; }
    { const char * tb_v14441 = "    if (!front) s = -s;\n"; *(const char * *)tb_grow(v_lines) = tb_v14441; }
    { const char * tb_v14442 = "    if (s < 0) s = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14442; }
    { const char * tb_v14443 = "    int k = L[3] + (((256 - L[3]) * (s >> 14)) >> 14);\n"; *(const char * *)tb_grow(v_lines) = tb_v14443; }
    { const char * tb_v14444 = "    uint32_t r = (((c >> 16) & 255) * (uint32_t)k + 128) >> 8, g = (((c >> 8) & 255) * (uint32_t)k + 128) >> 8, b = ((c & 255) * (uint32_t)k + 128) >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v14444; }
    { const char * tb_v14445 = "    return (c & 0xFF000000u) | (r << 16) | (g << 8) | b;\n"; *(const char * *)tb_grow(v_lines) = tb_v14445; }
    { const char * tb_v14446 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14446; }
    { const char * tb_v14447 = "// плоскость глубины по трём точкам экрана (x, y, D); 0 — треугольник ребром к нам, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v14447; }
    { const char * tb_v14448 = "TB_INL int tb_tri3_plane(const double *sx, const double *sy, const double *dd, uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14448; }
    { const char * tb_v14449 = "    double e1x = sx[1] - sx[0], e1y = sy[1] - sy[0], e2x = sx[2] - sx[0], e2y = sy[2] - sy[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v14449; }
    { const char * tb_v14450 = "    double area = e1x * e2y - e1y * e2x;\n"; *(const char * *)tb_grow(v_lines) = tb_v14450; }
    { const char * tb_v14451 = "    if (fabs(area) < 0.5) return 0;   // смотрит на нас ребром: точек почти нет\n"; *(const char * *)tb_grow(v_lines) = tb_v14451; }
    { const char * tb_v14452 = "    double ia = 1 / area;\n"; *(const char * *)tb_grow(v_lines) = tb_v14452; }
