    { const char * tb_v14474 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14474; }
    { const char * tb_v14475 = "// (u, v) угла в 1/16 точки картинки, не дальше ±2^19 (чтобы плоскости влезли в 64 бита)\n"; *(const char * *)tb_grow(v_lines) = tb_v14475; }
    { const char * tb_v14476 = "TB_INL long long tb_tex_q(double u, int w) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14476; }
    { const char * tb_v14477 = "    double q = u * w * 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v14477; }
    { const char * tb_v14478 = "    if (!(q > -524288)) q = -524288;   // и NaN\n"; *(const char * *)tb_grow(v_lines) = tb_v14478; }
    { const char * tb_v14479 = "    if (q > 524288) q = 524288;\n"; *(const char * *)tb_grow(v_lines) = tb_v14479; }
    { const char * tb_v14480 = "    return tb_rnd(q);\n"; *(const char * *)tb_grow(v_lines) = tb_v14480; }
    { const char * tb_v14481 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14481; }
    { const char * tb_v14482 = "// плоскость S по трём углам в целых: та же формула, что у плоскости глубины в tb_m3_tri\n"; *(const char * *)tb_grow(v_lines) = tb_v14482; }
    { const char * tb_v14483 = "static void tb_tex_plane_i(const long long *a, const long long *b, const long long *c, const long long *S, int64_t *o) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14483; }
    { const char * tb_v14484 = "    long long s0 = S[0], s1 = S[1], s2 = S[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v14484; }
    { const char * tb_v14485 = "    long long area = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v14485; }
    { const char * tb_v14486 = "    if (area < 0) { const long long *k = b; b = c; c = k; long long ks = s1; s1 = s2; s2 = ks; area = -area; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14486; }
    { const char * tb_v14487 = "    if (area == 0) { o[0] = o[1] = 0; o[2] = 64 * s0; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14487; }
    { const char * tb_v14488 = "    long long e1x = b[0] - a[0], e1y = b[1] - a[1], e2x = c[0] - a[0], e2y = c[1] - a[1], d1 = s1 - s0, d2 = s2 - s0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14488; }
    { const char * tb_v14489 = "    long long A = tb_fdiv(64 * (d1 * e2y - d2 * e1y) + area, 2 * area), B = tb_fdiv(64 * (d2 * e1x - d1 * e2x) + area, 2 * area);\n"; *(const char * *)tb_grow(v_lines) = tb_v14489; }
    { const char * tb_v14490 = "    o[0] = A; o[1] = B; o[2] = 64 * s0 - 2 * A * a[0] - 2 * B * a[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v14490; }
    { const char * tb_v14491 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14491; }
    { const char * tb_v14492 = "// запись текстуры для углов (x, y, D) в целых и (u, v) углов треугольника t\n"; *(const char * *)tb_grow(v_lines) = tb_v14492; }
    { const char * tb_v14493 = "static void tb_tex_rec_i(const tb_mesh *m, long long t, const long long *a, const long long *b, const long long *c, tb_gtex_t *tx) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14493; }
    { const char * tb_v14494 = "    const tb_image *im = &tb_imgs[m->tex];\n"; *(const char * *)tb_grow(v_lines) = tb_v14494; }
    { const char * tb_v14495 = "    const double *q = m->uv + 6 * t;\n"; *(const char * *)tb_grow(v_lines) = tb_v14495; }
    { const char * tb_v14496 = "    const long long *p[3] = { a, b, c };\n"; *(const char * *)tb_grow(v_lines) = tb_v14496; }
    { const char * tb_v14497 = "    long long su[3], sv[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v14497; }
    { const char * tb_v14498 = "    for (int i = 0; i < 3; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14498; }
    { const char * tb_v14499 = "        long long W = (16777216 - p[i][2]) >> 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v14499; }
    { const char * tb_v14500 = "        if (W < 1) W = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14500; }
    { const char * tb_v14501 = "        su[i] = tb_tex_q(q[2 * i], im->w) * W; sv[i] = tb_tex_q(q[2 * i + 1], im->h) * W;\n"; *(const char * *)tb_grow(v_lines) = tb_v14501; }
    { const char * tb_v14502 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14502; }
    { const char * tb_v14503 = "    int64_t pu[3], pv[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v14503; }
    { const char * tb_v14504 = "    tb_tex_plane_i(a, b, c, su, pu); tb_tex_plane_i(a, b, c, sv, pv);\n"; *(const char * *)tb_grow(v_lines) = tb_v14504; }
    { const char * tb_v14505 = "    tx->au = pu[0]; tx->bu = pu[1]; tx->cu = pu[2]; tx->av = pv[0]; tx->bv = pv[1]; tx->cv = pv[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v14505; }
    { const char * tb_v14506 = "    tx->off = im->off; tx->w = (uint32_t)im->w; tx->h = (uint32_t)im->h; tx->pad = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14506; }
    { const char * tb_v14507 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14507; }
    { const char * tb_v14508 = "// то же в дробях (старый путь): углы (x, y, D) после проекции и (u, v) каждого угла\n"; *(const char * *)tb_grow(v_lines) = tb_v14508; }
    { const char * tb_v14509 = "static void tb_tex_rec_d(const tb_mesh *m, int n, const double *sx, const double *sy, const double *dd, const double *uu, const double *vv, tb_gtex_t *tx) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14509; }
    { const char * tb_v14510 = "    const tb_image *im = &tb_imgs[m->tex];\n"; *(const char * *)tb_grow(v_lines) = tb_v14510; }
