    { const char * tb_v14512 = "    for (int i = 0; i < 3; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14512; }
    { const char * tb_v14513 = "        double W = floor((16777216 - dd[i]) / 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v14513; }
    { const char * tb_v14514 = "        if (W < 1) W = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14514; }
    { const char * tb_v14515 = "        su[i] = (double)tb_tex_q(uu[i], im->w) * W; sv[i] = (double)tb_tex_q(vv[i], im->h) * W;\n"; *(const char * *)tb_grow(v_lines) = tb_v14515; }
    { const char * tb_v14516 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14516; }
    { const char * tb_v14517 = "    (void)n;\n"; *(const char * *)tb_grow(v_lines) = tb_v14517; }
    { const char * tb_v14518 = "    double e1x = sx[1] - sx[0], e1y = sy[1] - sy[0], e2x = sx[2] - sx[0], e2y = sy[2] - sy[0], area = e1x * e2y - e1y * e2x;\n"; *(const char * *)tb_grow(v_lines) = tb_v14518; }
    { const char * tb_v14519 = "    double *S[2] = { su, sv };\n"; *(const char * *)tb_grow(v_lines) = tb_v14519; }
    { const char * tb_v14520 = "    int64_t o[6];\n"; *(const char * *)tb_grow(v_lines) = tb_v14520; }
    { const char * tb_v14521 = "    for (int k = 0; k < 2; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14521; }
    { const char * tb_v14522 = "        double ax = 0, by = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14522; }
    { const char * tb_v14523 = "        if (fabs(area) >= 1e-9) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14523; }
    { const char * tb_v14524 = "            ax = ((S[k][1] - S[k][0]) * e2y - (S[k][2] - S[k][0]) * e1y) / area;\n"; *(const char * *)tb_grow(v_lines) = tb_v14524; }
    { const char * tb_v14525 = "            by = ((S[k][2] - S[k][0]) * e1x - (S[k][1] - S[k][0]) * e2x) / area;\n"; *(const char * *)tb_grow(v_lines) = tb_v14525; }
