    { const char * tb_v14527 = "        if (ax > 1e15) ax = 1e15;\n"; *(const char * *)tb_grow(v_lines) = tb_v14527; }
    { const char * tb_v14528 = "        if (ax < -1e15) ax = -1e15;\n"; *(const char * *)tb_grow(v_lines) = tb_v14528; }
    { const char * tb_v14529 = "        if (by > 1e15) by = 1e15;\n"; *(const char * *)tb_grow(v_lines) = tb_v14529; }
    { const char * tb_v14530 = "        if (by < -1e15) by = -1e15;\n"; *(const char * *)tb_grow(v_lines) = tb_v14530; }
    { const char * tb_v14531 = "        double c0 = S[k][0] - ax * sx[0] - by * sy[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v14531; }
    { const char * tb_v14532 = "        o[3 * k] = tb_rnd(ax * 32); o[3 * k + 1] = tb_rnd(by * 32); o[3 * k + 2] = tb_rnd(c0 * 64);\n"; *(const char * *)tb_grow(v_lines) = tb_v14532; }
    { const char * tb_v14533 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14533; }
