    { const char * tb_v14535 = "    tx->off = im->off; tx->w = (uint32_t)im->w; tx->h = (uint32_t)im->h; tx->pad = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14535; }
    { const char * tb_v14536 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14536; }
    { const char * tb_v14537 = "// R — поворот сетки (3 × 3): угол p в мире = R p + (x, y, z)\n"; *(const char * *)tb_grow(v_lines) = tb_v14537; }
