    { const char * tb_v14633 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14633; }
    { const char * tb_v14634 = "// фокус экрана × 256 (угол обзора 60°)\n"; *(const char * *)tb_grow(v_lines) = tb_v14634; }
    { const char * tb_v14635 = "TB_INL long long tb_m3_f(void) { return tb_rnd(tb_gh / 2.0 / tan(30 * 3.14159265358979323846 / 180) * 256); }\n"; *(const char * *)tb_grow(v_lines) = tb_v14635; }
    { const char * tb_v14636 = "// угол сетки p (× 4096) по записи r: место на экране (целые точки) и глубина D = 2^24 - 2^24 * zn / z, zn = 205 / 4096\n"; *(const char * *)tb_grow(v_lines) = tb_v14636; }
    { const char * tb_v14637 = "TB_INL void tb_m3_corner(const int32_t *r, const int32_t *p, long long f, long long *o) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14637; }
    { const char * tb_v14638 = "    long long c[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v14638; }
    { const char * tb_v14639 = "    for (int k = 0; k < 3; k++)\n"; *(const char * *)tb_grow(v_lines) = tb_v14639; }
    { const char * tb_v14640 = "        c[k] = (((long long)r[4 * k] * p[0] + (long long)r[4 * k + 1] * p[1] + (long long)r[4 * k + 2] * p[2]) >> 30) + r[4 * k + 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v14640; }
    { const char * tb_v14641 = "    o[0] = ((long long)tb_gw * 128 + tb_fdiv(f * c[0], c[2]) + 128) >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v14641; }
    { const char * tb_v14642 = "    o[1] = ((long long)tb_gh * 128 - tb_fdiv(f * c[1], c[2]) + 128) >> 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v14642; }
    { const char * tb_v14643 = "    o[2] = 16777216 - tb_fdiv(205LL << 24, c[2]);\n"; *(const char * *)tb_grow(v_lines) = tb_v14643; }
    { const char * tb_v14644 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14644; }
    { const char * tb_v14645 = "// треугольник a, b, c (x, y, D): 0 — рисовать нечего (ребром к нам или невидимая грань); иначе углы\n"; *(const char * *)tb_grow(v_lines) = tb_v14645; }
    { const char * tb_v14646 = "// по кругу «как надо» в t и плоскость глубины в pl — то же, что tb_tri3_plane, только в целых\n"; *(const char * *)tb_grow(v_lines) = tb_v14646; }
    { const char * tb_v14647 = "TB_INL int tb_m3_tri(const long long *a, const long long *b, const long long *c, int cull, long long *t, uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14647; }
    { const char * tb_v14648 = "    long long area = (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v14648; }
    { const char * tb_v14649 = "    if (area == 0 || (cull > 0 && area > 0) || (cull < 0 && area < 0)) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14649; }
    { const char * tb_v14650 = "    int ret = area > 0 ? 1 : 2;   // 1 — грань смотрит на нас, 2 — спиной\n"; *(const char * *)tb_grow(v_lines) = tb_v14650; }
    { const char * tb_v14651 = "    if (area < 0) { const long long *k = b; b = c; c = k; area = -area; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14651; }
    { const char * tb_v14652 = "    long long e1x = b[0] - a[0], e1y = b[1] - a[1], e2x = c[0] - a[0], e2y = c[1] - a[1], d1 = b[2] - a[2], d2 = c[2] - a[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v14652; }
    { const char * tb_v14653 = "    long long A = tb_fdiv(64 * (d1 * e2y - d2 * e1y) + area, 2 * area), B = tb_fdiv(64 * (d2 * e1x - d1 * e2x) + area, 2 * area);\n"; *(const char * *)tb_grow(v_lines) = tb_v14653; }
    { const char * tb_v14654 = "    long long C = 64 * a[2] - 2 * A * a[0] - 2 * B * a[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v14654; }
    { const char * tb_v14655 = "    pl[0] = (uint32_t)A; pl[1] = (uint32_t)B; pl[2] = (uint32_t)C;\n"; *(const char * *)tb_grow(v_lines) = tb_v14655; }
    { const char * tb_v14656 = "    t[0] = a[0]; t[1] = a[1]; t[2] = b[0]; t[3] = b[1]; t[4] = c[0]; t[5] = c[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v14656; }
    { const char * tb_v14657 = "    return ret;\n"; *(const char * *)tb_grow(v_lines) = tb_v14657; }
    { const char * tb_v14658 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14658; }
    { const char * tb_v14659 = "// закрытая сетка (каждая сторона треугольника есть и в обратную сторону у соседа): грань, повёрнутая\n"; *(const char * *)tb_grow(v_lines) = tb_v14659; }
    { const char * tb_v14660 = "// от камеры, всегда закрыта другими гранями — и у куба снаружи, и у комнаты изнутри (грани внутрь).\n"; *(const char * *)tb_grow(v_lines) = tb_v14660; }
    { const char * tb_v14661 = "// Повёрнута от камеры = на экране по часовой стрелке (площадь < 0). 0 — рисовать все, -1 — пропускать такие\n"; *(const char * *)tb_grow(v_lines) = tb_v14661; }
    { const char * tb_v14662 = "static int tb_cmp_u64(const void *a, const void *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14662; }
    { const char * tb_v14663 = "    uint64_t x = *(const uint64_t *)a, y = *(const uint64_t *)b;\n"; *(const char * *)tb_grow(v_lines) = tb_v14663; }
    { const char * tb_v14664 = "    return x < y ? -1 : x > y;\n"; *(const char * *)tb_grow(v_lines) = tb_v14664; }
    { const char * tb_v14665 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14665; }
    { const char * tb_v14666 = "static int tb_mesh_cull(tb_mesh *m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14666; }
    { const char * tb_v14667 = "    if (m->cullok) return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v14667; }
    { const char * tb_v14668 = "    m->cullok = 1; m->cull = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14668; }
    { const char * tb_v14669 = "    long long ne = 3 * m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v14669; }
    { const char * tb_v14670 = "    uint64_t *e = (uint64_t *)malloc(sizeof(uint64_t) * (size_t)(ne ? ne : 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v14670; }
    { const char * tb_v14671 = "    double vol = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14671; }
    { const char * tb_v14672 = "    for (long long t = 0; t < m->n; t++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14672; }
    { const char * tb_v14673 = "        const uint32_t *ti = m->t + 3 * t;\n"; *(const char * *)tb_grow(v_lines) = tb_v14673; }
    { const char * tb_v14674 = "        for (int k = 0; k < 3; k++) e[3 * t + k] = ((uint64_t)ti[k] << 32) | ti[(k + 1) % 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v14674; }
    { const char * tb_v14675 = "        const double *p = m->v + 3 * ti[0], *q = m->v + 3 * ti[1], *r = m->v + 3 * ti[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v14675; }
    { const char * tb_v14676 = "        vol += p[0] * (q[1] * r[2] - q[2] * r[1]) + p[1] * (q[2] * r[0] - q[0] * r[2]) + p[2] * (q[0] * r[1] - q[1] * r[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v14676; }
    { const char * tb_v14677 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14677; }
    { const char * tb_v14678 = "    qsort(e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64);\n"; *(const char * *)tb_grow(v_lines) = tb_v14678; }
    { const char * tb_v14679 = "    int closed = ne > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14679; }
    { const char * tb_v14680 = "    for (long long i = 0; i < ne && closed; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14680; }
    { const char * tb_v14681 = "        if (i + 1 < ne && e[i] == e[i + 1]) closed = 0;   // одна сторона дважды в одну сторону\n"; *(const char * *)tb_grow(v_lines) = tb_v14681; }
    { const char * tb_v14682 = "        uint64_t back = (e[i] << 32) | (e[i] >> 32);\n"; *(const char * *)tb_grow(v_lines) = tb_v14682; }
    { const char * tb_v14683 = "        if ((uint32_t)e[i] == (uint32_t)(e[i] >> 32) || !bsearch(&back, e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64)) closed = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14683; }
    { const char * tb_v14684 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14684; }
    { const char * tb_v14685 = "    free(e);\n"; *(const char * *)tb_grow(v_lines) = tb_v14685; }
    { const char * tb_v14686 = "    if (closed && fabs(vol) > 1e-12) m->cull = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14686; }
    { const char * tb_v14687 = "    return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v14687; }
    { const char * tb_v14688 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14688; }
    { const char * tb_v14689 = "// сетки для видеокарты: у каждой сначала углы (x, y, z, 0), потом треугольники по две строки:\n"; *(const char * *)tb_grow(v_lines) = tb_v14689; }
    { const char * tb_v14690 = "// (номера углов, цвет) и (нормаль × 2^14, -1)\n"; *(const char * *)tb_grow(v_lines) = tb_v14690; }
    { const char * tb_v14691 = "TB_API long long tb_mesh_pack(int32_t *dst) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14691; }
    { const char * tb_v14692 = "    long long at = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14692; }
