    { const char * tb_v14702 = "                for (int k = 0; k < 3; k++) o[k] = (int32_t)(m->t[3 * t + k] + m->gv);\n"; *(const char * *)tb_grow(v_lines) = tb_v14702; }
    { const char * tb_v14703 = "                o[3] = (int32_t)(m->c[t] & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v14703; }
