    { const char * tb_v14706 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v14706; }
    { const char * tb_v14707 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v14707; }
    { const char * tb_v14708 = "        at += m->nv + 2 * m->n;\n"; *(const char * *)tb_grow(v_lines) = tb_v14708; }
    { const char * tb_v14709 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v14709; }
    { const char * tb_v14710 = "    return at;\n"; *(const char * *)tb_grow(v_lines) = tb_v14710; }
    { const char * tb_v14711 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14711; }
    { const char * tb_v14712 = "TB_API void tb_mesh_gpc(const tb_ginst *g, int slot, tb_gpc *pc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14712; }
