    { const char * tb_v14715 = "    pc->tbase = (int32_t)(m->gt + 2 * g->ox); pc->ntri = g->oy; pc->rbase = (slot * TB_GR_CAP + g->x1) * 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v14715; }
