    { const char * tb_v14719 = "TB_API long long tb_3icap = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14719; }
    { const char * tb_v14720 = "// шар сетки или куска (центр в сетке, радиус) после камеры: 0 — не видно совсем (за камерой или вне экрана\n"; *(const char * *)tb_grow(v_lines) = tb_v14720; }
    { const char * tb_v14721 = "// с запасом 2 точки), 1 — целые годятся (весь перед камерой, на экране не дальше ±8100 точек), 2 — старый путь\n"; *(const char * *)tb_grow(v_lines) = tb_v14721; }
    { const char * tb_v14722 = "static int tb_m3_test(const double *sp, double M[3][3], const double *T, double f, int big) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14722; }
    { const char * tb_v14723 = "    double cc[3], rad = sp[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v14723; }
    { const char * tb_v14724 = "    for (int k = 0; k < 3; k++) cc[k] = M[k][0] * sp[0] + M[k][1] * sp[1] + M[k][2] * sp[2] + T[k];\n"; *(const char * *)tb_grow(v_lines) = tb_v14724; }
    { const char * tb_v14725 = "    if (cc[2] + rad < 205.0 / 4096) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14725; }
    { const char * tb_v14726 = "    double hw = tb_gw / 2.0 + 2, hh = tb_gh / 2.0 + 2, lx = sqrt(f * f + hw * hw), ly = sqrt(f * f + hh * hh);\n"; *(const char * *)tb_grow(v_lines) = tb_v14726; }
    { const char * tb_v14727 = "    if ((f * cc[0] - hw * cc[2]) / lx > rad || (-f * cc[0] - hw * cc[2]) / lx > rad) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14727; }
    { const char * tb_v14728 = "    if ((f * cc[1] - hh * cc[2]) / ly > rad || (-f * cc[1] - hh * cc[2]) / ly > rad) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14728; }
    { const char * tb_v14729 = "    double zmin = cc[2] - rad;\n"; *(const char * *)tb_grow(v_lines) = tb_v14729; }
    { const char * tb_v14730 = "    int ok = !big && zmin >= 0.12 && fabs(T[0]) < 400000 && fabs(T[1]) < 400000 && fabs(T[2]) < 400000 &&\n"; *(const char * *)tb_grow(v_lines) = tb_v14730; }
    { const char * tb_v14731 = "             fabs(cc[0]) + rad < 400000 && fabs(cc[1]) + rad < 400000 && cc[2] + rad < 400000;\n"; *(const char * *)tb_grow(v_lines) = tb_v14731; }
    { const char * tb_v14732 = "    if (ok) ok = tb_gw / 2.0 + f * (fabs(cc[0]) + rad) / zmin < 8100 && tb_gh / 2.0 + f * (fabs(cc[1]) + rad) / zmin < 8100;\n"; *(const char * *)tb_grow(v_lines) = tb_v14732; }
    { const char * tb_v14733 = "    return ok ? 1 : 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v14733; }
    { const char * tb_v14734 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14734; }
    { const char * tb_v14735 = "// один draw_mesh в целых: запись (одна на вызов, в текущем наборе) и куски треугольников\n"; *(const char * *)tb_grow(v_lines) = tb_v14735; }
