    { const char * tb_v14939 = "    if (m->nch <= 1) { tb_draw_mesh_d(m, x, y, z, R, L, 0, m->n); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14939; }
    { const char * tb_v14940 = "    // сетка большая и задевает камеру или край: по кускам — дальние на видеокарте, ближние старым путём\n"; *(const char * *)tb_grow(v_lines) = tb_v14940; }
