    { const char * tb_v14959 = "TB_API double tb_amb0 = 0;               // фон, когда солнца нет (sunlight(0, 0, 0, фон)), а лампы горят\n"; *(const char * *)tb_grow(v_lines) = tb_v14959; }
    { const char * tb_v14960 = "TB_API int tb_fog_on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14960; }
