    { const char * tb_v14971 = "// сетка рисуется новым путём? (свои настройки сетки или что-то общее для всей сцены)\n"; *(const char * *)tb_grow(v_lines) = tb_v14971; }
    { const char * tb_v14972 = "TB_INL int tb_lit_mesh(const tb_mesh *m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14972; }
    { const char * tb_v14973 = "    return m->smooth || m->shine > 0 || m->glow > 0 || m->alpha < 255 || m->nb > 0 || tb_nlamps > 0 || tb_fog_on || tb_sh_size > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14973; }
    { const char * tb_v14974 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14974; }
    { const char * tb_v14975 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v14975; }
    { const char * tb_v14976 = "// ---- лампы, туман, тени ----\n"; *(const char * *)tb_grow(v_lines) = tb_v14976; }
    { const char * tb_v14977 = "static void tb_lamps_count(void) { tb_nlamps = 0; for (int i = 0; i < 8; i++) tb_nlamps += tb_lamps[i].on; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14977; }
    { const char * tb_v14978 = "static void tb_rgb01(long long c, double *o) { o[0] = ((c >> 16) & 255) / 255.0; o[1] = ((c >> 8) & 255) / 255.0; o[2] = (c & 255) / 255.0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14978; }
    { const char * tb_v14979 = "TB_API void tb_point_light(long long n, double x, double y, double z, long long c, double range) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14979; }
    { const char * tb_v14980 = "    if (n < 0 || n > 7) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14980; }
    { const char * tb_v14981 = "    tb_scene_flush();\n"; *(const char * *)tb_grow(v_lines) = tb_v14981; }
    { const char * tb_v14982 = "    tb_lamp_t *l = &tb_lamps[n];\n"; *(const char * *)tb_grow(v_lines) = tb_v14982; }
    { const char * tb_v14983 = "    l->on = range > 0 && fabs(x) < 1e300 && fabs(y) < 1e300 && fabs(z) < 1e300; l->spot = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v14983; }
    { const char * tb_v14984 = "    l->p[0] = x; l->p[1] = y; l->p[2] = z; l->range = range;\n"; *(const char * *)tb_grow(v_lines) = tb_v14984; }
    { const char * tb_v14985 = "    tb_rgb01(c, l->col);\n"; *(const char * *)tb_grow(v_lines) = tb_v14985; }
