    { const char * tb_v14987 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v14987; }
    { const char * tb_v14988 = "// фонарь: светит конусом шириной angle градусов в сторону (dx, dy, dz); край конуса мягкий\n"; *(const char * *)tb_grow(v_lines) = tb_v14988; }
    { const char * tb_v14989 = "TB_API void tb_spot_light(long long n, double x, double y, double z, double dx, double dy, double dz, double angle, long long c, double range) {\n"; *(const char * *)tb_grow(v_lines) = tb_v14989; }
    { const char * tb_v14990 = "    if (n < 0 || n > 7) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v14990; }
    { const char * tb_v14991 = "    tb_point_light(n, x, y, z, c, range);\n"; *(const char * *)tb_grow(v_lines) = tb_v14991; }
    { const char * tb_v14992 = "    tb_lamp_t *l = &tb_lamps[n];\n"; *(const char * *)tb_grow(v_lines) = tb_v14992; }
    { const char * tb_v14993 = "    double d = sqrt(dx * dx + dy * dy + dz * dz);\n"; *(const char * *)tb_grow(v_lines) = tb_v14993; }
    { const char * tb_v14994 = "    if (!(d > 1e-12) || !(angle > 0)) { l->on = 0; tb_lamps_count(); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v14994; }
    { const char * tb_v14995 = "    if (angle > 179) angle = 179;\n"; *(const char * *)tb_grow(v_lines) = tb_v14995; }
    { const char * tb_v14996 = "    l->spot = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v14996; }
    { const char * tb_v14997 = "    l->d[0] = dx / d; l->d[1] = dy / d; l->d[2] = dz / d;\n"; *(const char * *)tb_grow(v_lines) = tb_v14997; }
    { const char * tb_v14998 = "    double h = angle / 2 * 3.14159265358979323846 / 180;\n"; *(const char * *)tb_grow(v_lines) = tb_v14998; }
    { const char * tb_v14999 = "    l->c1 = cos(h); l->c0 = cos(h * 0.75);   // от c0 к краю c1 свет плавно гаснет\n"; *(const char * *)tb_grow(v_lines) = tb_v14999; }
    { const char * tb_v15000 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v15000; }
    { const char * tb_v15001 = "TB_API void tb_light_off(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v15001; }
    { const char * tb_v15002 = "    if (n < 0 || n > 7) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v15002; }
    { const char * tb_v15003 = "    tb_scene_flush();\n"; *(const char * *)tb_grow(v_lines) = tb_v15003; }
    { const char * tb_v15004 = "    tb_lamps[n].on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v15004; }
    { const char * tb_v15005 = "    tb_lamps_count();\n"; *(const char * *)tb_grow(v_lines) = tb_v15005; }
    { const char * tb_v15006 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v15006; }
    { const char * tb_v15007 = "// туман: с расстояния near цвет уходит в c, дальше far — весь c; fog(0, 0, 0) — без тумана\n"; *(const char * *)tb_grow(v_lines) = tb_v15007; }
    { const char * tb_v15008 = "TB_API void tb_fog(long long c, double n, double f) {\n"; *(const char * *)tb_grow(v_lines) = tb_v15008; }
    { const char * tb_v15009 = "    tb_scene_flush();\n"; *(const char * *)tb_grow(v_lines) = tb_v15009; }
    { const char * tb_v15010 = "    if (!(n >= 0)) n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v15010; }
    { const char * tb_v15011 = "    tb_fog_on = f > n;\n"; *(const char * *)tb_grow(v_lines) = tb_v15011; }
    { const char * tb_v15012 = "    tb_fog_c = (uint32_t)c & 0xFFFFFF; tb_fog_n = n; tb_fog_f = f;\n"; *(const char * *)tb_grow(v_lines) = tb_v15012; }
    { const char * tb_v15013 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v15013; }
    { const char * tb_v15014 = "// тени от солнца в квадрате size × size вокруг камеры; 0 — без теней\n"; *(const char * *)tb_grow(v_lines) = tb_v15014; }
    { const char * tb_v15015 = "TB_API void tb_shadows(double size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v15015; }
    { const char * tb_v15016 = "    tb_scene_flush();\n"; *(const char * *)tb_grow(v_lines) = tb_v15016; }
    { const char * tb_v15017 = "    tb_sh_size = size > 0 && size < 1e6 ? size : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v15017; }
    { const char * tb_v15018 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v15018; }
    { const char * tb_v15019 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v15019; }
    { const char * tb_v15020 = "// ---- свойства сетки ----\n"; *(const char * *)tb_grow(v_lines) = tb_v15020; }
    { const char * tb_v15021 = "TB_API void tb_mesh_smooth(long long id, int on) {\n"; *(const char * *)tb_grow(v_lines) = tb_v15021; }
    { const char * tb_v15022 = "    if (id < 0 || id >= tb_nmesh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v15022; }
    { const char * tb_v15023 = "    tb_scene_flush();\n"; *(const char * *)tb_grow(v_lines) = tb_v15023; }
    { const char * tb_v15024 = "    tb_meshes[id].smooth = on != 0; tb_meshes[id].cnok = 0; tb_meshes[id].shok = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v15024; }
    { const char * tb_v15025 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v15025; }
    { const char * tb_v15026 = "TB_INL double tb_01(double v) { return v > 0 ? (v < 1 ? v : 1) : 0; }   // и NaN — 0\n"; *(const char * *)tb_grow(v_lines) = tb_v15026; }
    { const char * tb_v15027 = "TB_API void tb_mesh_shine(long long id, double s) { if (id >= 0 && id < tb_nmesh) tb_meshes[id].shine = tb_01(s); }\n"; *(const char * *)tb_grow(v_lines) = tb_v15027; }
    { const char * tb_v15028 = "TB_API void tb_mesh_glow(long long id, double g) { if (id >= 0 && id < tb_nmesh) tb_meshes[id].glow = tb_01(g); }\n"; *(const char * *)tb_grow(v_lines) = tb_v15028; }
    { const char * tb_v15029 = "TB_API void tb_mesh_alpha(long long id, double a) { if (id >= 0 && id < tb_nmesh) { tb_meshes[id].alpha = (int)tb_rnd(tb_01(a) * 255); tb_meshes[id].shok = 0; } }\n"; *(const char * *)tb_grow(v_lines) = tb_v15029; }
    { const char * tb_v15030 = "TB_API long long tb_mesh_count(long long id) { return id >= 0 && id < tb_nmesh ? tb_meshes[id].n : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v15030; }
    { const char * tb_v15031 = "// стереть все треугольники сетки (кости остаются): сетку можно собрать заново — так меняют блоки мира\n"; *(const char * *)tb_grow(v_lines) = tb_v15031; }
    { const char * tb_v15032 = "TB_API void tb_mesh_clear(long long id) {\n"; *(const char * *)tb_grow(v_lines) = tb_v15032; }
    { const char * tb_v15033 = "    if (id < 0 || id >= tb_nmesh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v15033; }
    { const char * tb_v15034 = "    tb_scene_flush();\n"; *(const char * *)tb_grow(v_lines) = tb_v15034; }
    { const char * tb_v15035 = "    tb_mesh *m = &tb_meshes[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v15035; }
