    { const char * tb_v15037 = "    free(m->hk); m->hk = 0; m->hcap = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v15037; }
    { const char * tb_v15038 = "    m->nv = 0; m->n = 0; m->big = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v15038; }
    { const char * tb_v15039 = "    m->cullok = m->chok = m->nrmok = m->cnok = m->shok = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v15039; }
    { const char * tb_v15040 = "    tb_mesh_gdirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v15040; }
    { const char * tb_v15041 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v15041; }
    { const char * tb_v15042 = "// mesh_free: сетка больше не нужна — память отдаётся, номер достанется следующему mesh_new\n"; *(const char * *)tb_grow(v_lines) = tb_v15042; }
    { const char * tb_v15043 = "// (старый номер больше не трогай: он будет у другой сетки). Для подгрузки мира кусками\n"; *(const char * *)tb_grow(v_lines) = tb_v15043; }
    { const char * tb_v15044 = "TB_API void tb_mesh_free(long long id) {\n"; *(const char * *)tb_grow(v_lines) = tb_v15044; }
    { const char * tb_v15045 = "    if (id < 0 || id >= tb_nmesh) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v15045; }
