    { const char * tb_v15990 = "static double tb_sh_t0 = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v15990; }
    { const char * tb_v15991 = "// углы сетки по порядку треугольников: место 3, нормаль 3, цвет 4, (u, v) 2, касательная 3 (куда растёт u), 1 пусто,\n"; *(const char * *)tb_grow(v_lines) = tb_v15991; }
    { const char * tb_v15992 = "// 4 кости и 4 веса (сумма не больше 1, остаток — на месте) — 24 числа\n"; *(const char * *)tb_grow(v_lines) = tb_v15992; }
    { const char * tb_v15993 = "enum { TB_SHV = 24 };\n"; *(const char * *)tb_grow(v_lines) = tb_v15993; }
