    { const char * tb_v16037 = "            T[0] = a[1] * N[2] - a[2] * N[1]; T[1] = a[2] * N[0] - a[0] * N[2]; T[2] = a[0] * N[1] - a[1] * N[0];\n"; *(const char * *)tb_grow(v_lines) = tb_v16037; }
    { const char * tb_v16038 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v16038; }
