    { const char * tb_v16402 = "    static int tried = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16402; }
    { const char * tb_v16403 = "    if (!tried) { tried = 1; dlopen(\"/System/Library/Frameworks/GameController.framework/GameController\", RTLD_LAZY); }\n"; *(const char * *)tb_grow(v_lines) = tb_v16403; }
    { const char * tb_v16404 = "    id cls = TB_CLS(\"GCController\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16404; }
    { const char * tb_v16405 = "    for (int p = 0; p < TB_PADS; p++) tb_pads[p].on = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16405; }
    { const char * tb_v16406 = "    if (!cls) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v16406; }
    { const char * tb_v16407 = "    id all = TB_MSG(id, cls, \"controllers\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16407; }
    { const char * tb_v16408 = "    unsigned long n = all ? TB_MSG(unsigned long, all, \"count\") : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16408; }
    { const char * tb_v16409 = "    for (unsigned long i = 0; i < n && i < TB_PADS; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16409; }
    { const char * tb_v16410 = "        id c = TB_MSG1(id, all, \"objectAtIndex:\", unsigned long, i);\n"; *(const char * *)tb_grow(v_lines) = tb_v16410; }
    { const char * tb_v16411 = "        id g = TB_MSG(id, c, \"extendedGamepad\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16411; }
    { const char * tb_v16412 = "        if (!g) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v16412; }
