    { const char * tb_v16414 = "        p->on = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v16414; }
    { const char * tb_v16415 = "        static const char *bn[TB_PB_N] = { \"buttonA\", \"buttonB\", \"buttonX\", \"buttonY\", \"leftShoulder\", \"rightShoulder\",\n"; *(const char * *)tb_grow(v_lines) = tb_v16415; }
    { const char * tb_v16416 = "            \"leftTrigger\", \"rightTrigger\", \"leftThumbstickButton\", \"rightThumbstickButton\", \"buttonMenu\", \"buttonOptions\", \"buttonHome\", 0, 0, 0, 0 };\n"; *(const char * *)tb_grow(v_lines) = tb_v16416; }
    { const char * tb_v16417 = "        for (int k = 0; k < TB_PB_N; k++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16417; }
    { const char * tb_v16418 = "            if (!bn[k]) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v16418; }
