    { const char * tb_v16425 = "        p->b[TB_PB_DOWN] = (int)TB_MSG(BOOL, TB_MSG(id, dp, \"down\"), \"isPressed\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16425; }
    { const char * tb_v16426 = "        p->b[TB_PB_LEFT] = (int)TB_MSG(BOOL, TB_MSG(id, dp, \"left\"), \"isPressed\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16426; }
    { const char * tb_v16427 = "        p->b[TB_PB_RIGHT] = (int)TB_MSG(BOOL, TB_MSG(id, dp, \"right\"), \"isPressed\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16427; }
    { const char * tb_v16428 = "        id ls = TB_MSG(id, g, \"leftThumbstick\"), rs = TB_MSG(id, g, \"rightThumbstick\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16428; }
    { const char * tb_v16429 = "        p->a[TB_PA_LX] = TB_MSG(float, TB_MSG(id, ls, \"xAxis\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16429; }
    { const char * tb_v16430 = "        p->a[TB_PA_LY] = -TB_MSG(float, TB_MSG(id, ls, \"yAxis\"), \"value\");   // у Apple вверх — плюс\n"; *(const char * *)tb_grow(v_lines) = tb_v16430; }
    { const char * tb_v16431 = "        p->a[TB_PA_RX] = TB_MSG(float, TB_MSG(id, rs, \"xAxis\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16431; }
    { const char * tb_v16432 = "        p->a[TB_PA_RY] = -TB_MSG(float, TB_MSG(id, rs, \"yAxis\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16432; }
    { const char * tb_v16433 = "        p->a[TB_PA_L2] = TB_MSG(float, TB_MSG(id, g, \"leftTrigger\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16433; }
    { const char * tb_v16434 = "        p->a[TB_PA_R2] = TB_MSG(float, TB_MSG(id, g, \"rightTrigger\"), \"value\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16434; }
    { const char * tb_v16435 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v16435; }
    { const char * tb_v16436 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v16436; }
    { const char * tb_v16437 = "#elif defined(_WIN32)\n"; *(const char * *)tb_grow(v_lines) = tb_v16437; }
    { const char * tb_v16438 = "typedef struct { unsigned short buttons; unsigned char lt, rt; short lx, ly, rx, ry; } tb_xpad;\n"; *(const char * *)tb_grow(v_lines) = tb_v16438; }
    { const char * tb_v16439 = "typedef struct { unsigned long packet; tb_xpad pad; } tb_xstate;\n"; *(const char * *)tb_grow(v_lines) = tb_v16439; }
    { const char * tb_v16440 = "TB_API void tb_pad_poll(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16440; }
    { const char * tb_v16441 = "    static unsigned long (__stdcall *get)(unsigned long, tb_xstate *) = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16441; }
    { const char * tb_v16442 = "    static int tried = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16442; }
    { const char * tb_v16443 = "    if (!tried) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16443; }
    { const char * tb_v16444 = "        tried = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v16444; }
    { const char * tb_v16445 = "        HMODULE h = LoadLibraryA(\"xinput1_4.dll\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16445; }
    { const char * tb_v16446 = "        if (!h) h = LoadLibraryA(\"xinput9_1_0.dll\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16446; }
    { const char * tb_v16447 = "        if (h) get = (unsigned long (__stdcall *)(unsigned long, tb_xstate *))GetProcAddress(h, \"XInputGetState\");\n"; *(const char * *)tb_grow(v_lines) = tb_v16447; }
    { const char * tb_v16448 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v16448; }
    { const char * tb_v16449 = "    for (int i = 0; i < TB_PADS; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v16449; }
    { const char * tb_v16450 = "        tb_pad *p = &tb_pads[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v16450; }
    { const char * tb_v16451 = "        tb_xstate st; memset(&st, 0, sizeof st);\n"; *(const char * *)tb_grow(v_lines) = tb_v16451; }
    { const char * tb_v16452 = "        p->on = get && get((unsigned long)i, &st) == 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16452; }
    { const char * tb_v16453 = "        if (!p->on) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v16453; }
    { const char * tb_v16454 = "        unsigned short w = st.pad.buttons;\n"; *(const char * *)tb_grow(v_lines) = tb_v16454; }
    { const char * tb_v16455 = "        static const unsigned short bit[TB_PB_N] = { 0x1000, 0x2000, 0x4000, 0x8000, 0x0100, 0x0200, 0, 0, 0x0040, 0x0080, 0x0010, 0x0020, 0, 0x0001, 0x0002, 0x0004, 0x0008 };\n"; *(const char * *)tb_grow(v_lines) = tb_v16455; }
    { const char * tb_v16456 = "        for (int k = 0; k < TB_PB_N; k++) p->b[k] = bit[k] ? (w & bit[k]) != 0 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16456; }
    { const char * tb_v16457 = "        p->b[TB_PB_L2] = st.pad.lt > 30; p->b[TB_PB_R2] = st.pad.rt > 30;\n"; *(const char * *)tb_grow(v_lines) = tb_v16457; }
    { const char * tb_v16458 = "        p->a[TB_PA_LX] = st.pad.lx / 32767.0; p->a[TB_PA_LY] = -st.pad.ly / 32767.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16458; }
    { const char * tb_v16459 = "        p->a[TB_PA_RX] = st.pad.rx / 32767.0; p->a[TB_PA_RY] = -st.pad.ry / 32767.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16459; }
    { const char * tb_v16460 = "        p->a[TB_PA_L2] = st.pad.lt / 255.0; p->a[TB_PA_R2] = st.pad.rt / 255.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v16460; }
    { const char * tb_v16461 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v16461; }
    { const char * tb_v16462 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v16462; }
    { const char * tb_v16463 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v16463; }
