    { const char * tb_v17018 = "        else if (i >= n - ramp) e = (double)(n - 1 - i) / ramp;\n"; *(const char * *)tb_grow(v_lines) = tb_v17018; }
    { const char * tb_v17019 = "        d[i] = (float)(0.5 * e * sin(6.283185307179586 * hz * (double)i / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v17019; }
    { const char * tb_v17020 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v17020; }
    { const char * tb_v17021 = "    long long s = tb_snd_add(d, n, 1, TB_SR, 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v17021; }
